pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let capacity_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect 2-step lookahead match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 310.0;
    }
    // Near-perfect lookahead match with graded slack handling.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 3.0 {
            score -= 185.0;
        } else if slack <= 14.0 {
            score -= (56.0 - slack * 0.7).max(-18.0);
        } else {
            score -= (40.0 - slack * 0.35).max(-22.0);
        }
        // Chain compaction: slack nearly closes bin after next item.
        if slack < 22.0 {
            score -= (22.0 - slack) * 1.8;
        }
        // Divisibility: residual divisible by next item keeps the chain tight.
        let rem = post_residual % next_item_size;
        if rem <= 3 {
            score -= 15.0 * (1.0 - progress);
        }
        let k = post_residual / next_item_size;
        if k >= 2 && post_residual - k * next_item_size <= 2 {
            score -= 21.0;
        }
        // Multi-step chain depth.
        let depth = post_residual / next_item_size.max(1);
        if depth >= 3 {
            score -= (depth.min(6) as f64) * 5.5 * (0.5 + progress);
        }
        // Dead-space ratio refinement — stronger penalty for large dead fraction.
        let next_waste = capacity_f - next_item_size as f64;
        if slack > next_waste * 0.55 {
            score += (slack - next_waste * 0.55) * 1.05 * (0.5 + progress);
        }
        // Extendable chain reward.
        if slack >= next_item_size as f64 {
            score -= 12.0 + 10.0 * progress;
        }
        // Near-multiple slack promises a longer chain.
        let mult = slack as u32 / next_item_size;
        let mrem = slack as u32 % next_item_size;
        if mult >= 1 && mrem <= 1 {
            score -= (mult.min(4) as f64) * 8.5 * (0.6 + progress);
        }
        // Exact 2x-next residual is a golden two-step chain.
        if post_residual == 2 * next_item_size {
            score -= 27.0 * (0.5 + progress);
        }
        // Spread lookahead rewards only on the tightest candidates.
        if fitting_bins_count > 2 && slack > 10.0 {
            score += (fitting_bins_count as f64 - 2.0).min(4.0) * 3.2;
        }
        // Tiny tail is near-perfect.
        if slack <= 2 {
            score -= 23.0 * (0.6 + progress);
        }
    }
    // Post-residual too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * (0.5 + 0.24 * gap / capacity_f);
        if gap <= 4.0 && post_f > 0.0 {
            score -= 17.0 * (1.0 - progress);
        }
        if gap <= 2.0 {
            score -= 13.0;
        }
        let rel = gap / (next_item_size as f64).max(1.0);
        score += rel * 27.0 * (0.6 + 0.4 * progress);
        if gap <= 12.0 && progress < 0.6 {
            score -= 7.5 * (1.0 - progress);
        }
        if gap > post_f * 0.6 {
            score += gap * 0.35 * progress;
        }
    }

    // Above-average residual left behind is good.
    score -= (post_f - mean_residual) * 0.58;

