        }
        if next_item_size > 0 && (next_item_size as i32 - fresh_res as i32).abs() < 6 {
            score += 15.0 * (1.0 - progress);
        }
        if item_size >= 60 && fresh_res <= 10 {
            score -= 42.0;
        }
        if item_size == bin_capacity {
            score -= 950.0;
        }
        if fitting_bins_count >= 1 && post_residual > 35 {
            score -= 33.0;
        }
        if open_bins_count > 2 && item_size as f64 > capacity_f * 0.8 {
            score += 27.0;
        }
        if fresh_f > 0.0 {
            score += (fresh_f / capacity_f) * 15.0 * progress;
        }
        if fresh_f > 18.0 && fresh_f < capacity_f * 0.45 {
            score += 9.5 * (1.0 - progress);
        }
        // Refuse a fresh bin when an existing bin yields a tight fit.
        if fitting_bins_count >= 1 {
            if post_residual as f64 <= 5.0 {
                score += 78.0;
            } else if post_f > capacity_f * 0.5 {
                score -= 31.0;
            } else if post_f <= capacity_f * 0.25 {
                score += 23.0 * (0.4 + 0.6 * progress);
            }
        }
        if progress < 0.2 && item_size as f64 > capacity_f * 0.65 {
            score -= 21.0;
        }
        // Fresh-bin residual quality — reusable residuals are cheap to open.
        if next_item_size > 0 {
            let ratio = fresh_f / (next_item_size.max(1) as f64);
            if ratio >= 1.0 && ratio < 2.0 {
                score -= 15.0;
            } else if fresh_f < 8.0 {
                score += 15.0;
            }
            if fresh_res == next_item_size {
                score -= 27.0 * (1.0 - progress);
            }
            let fmult = fresh_res / next_item_size;
            let frem = fresh_res % next_item_size;
            if fmult >= 2 && frem <= 2 {
                score -= (fmult.min(5) as f64) * 5.5;
            }
            // Awkward fractional multiples seed fragmentation.
            let frac = ratio - ratio.floor();
            if ratio >= 1.0 && frac > 0.05 && frac < 0.4 {
                score += 11.0 * (0.5 + progress);
            }
            // NEW: fresh residual that is an awkward leftover (< next item and
            // small) is dead space from birth — penalize more mid-stream.
            if fresh_f < next_item_size as f64 && fresh_f > 0.0 && progress > 0.35 {
                score += (next_item_size as f64 - fresh_f) * 0.55 * progress;
            }
            // NEW: fresh residual that can absorb the next item exactly once
            // (residual == next) is a perfect future closure — reward.
            if fresh_res == next_item_size {
                score -= 12.0 * (0.5 + progress);
            }
        }
        // Never open a fresh bin when the item nearly fills an existing bin exactly.
        if fitting_bins_count >= 1 && bin_capacity - item_size <= 2 {
            score += 50.0;
        }
        // Late-stream fresh bins must be nearly self-closing.
        if progress > 0.7 && fresh_f > 0.0 && fresh_f < next_item_size.max(1) as f64 {
            score += 31.0 * progress;
        }
        if progress > 0.75 && fresh_f >= 12.0 {
            score += 19.0 * (progress - 0.75) * 4.0;
        }
        if progress > 0.8 && open_bins_count > 6 && fresh_f > 4.0 {
            score += 21.0 * progress;
        }
        // NEW: opening a fresh bin is more acceptable when many bins are open
        // and the best existing post-residual is large (consolidation pressure).
        if fitting_bins_count >= 1 && open_bins_count > 5 && post_f > capacity_f * 0.35 {
            score -= 14.0 * ((open_bins_count as f64 - 5.0).min(6.0) / 6.0);
        }
    }

    // Waste-proportional penalty scaled by progress.
    if post_f > 0.0 {
        score += (post_f / capacity_f) * (1.0 + progress) * (1.0 + 0.55 * progress);
    }
    // Tightness term.
    score += (post_f / capacity_f) * (1.0 + progress);

    // Prefer consolidating into fewer open bins.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.6;
    }

    // Nearly-dead bins are cheap to use up.
    if (bin_residual as f64) < mean_residual * 0.3 && bin_residual < bin_capacity {
        score -= 19.0;
    }

    // Half-capacity dead zones seed fragmentation.
    let half = capacity_f * 0.5;
    if post_f > half - 6.0 && post_f < half + 6.0 {
        score += 10.5 * (1.0 - progress);
    }
    if post_f > half && post_f < half + 12.0 {
        score += 6.5 * progress;
    }
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.2 * (0.4 + progress);
    }
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.42 * progress;
    }

    // Quarter/three-quarter awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // Late-stream zero-tolerance.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // NEW: dead-space ratio term — penalize candidates whose post-residual
    // cannot pair with the next item even at half its size (true dead space).
    if next_item_size > 0 && post_f > 0.0 && post_f < (next_item_size as f64) * 0.5 {
        score += ((next_item_size as f64) * 0.5 - post_f) * 0.35 * (0.5 + progress);
    }

    // NEW: combined fit-lookahead coupling — when many bins fit the item but
    // only one yields a post-residual that can host the next item, favor it.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        score -= 6.0 * (1.0 - progress) * (1.0 - (fitting_bins_count.min(6) as f64 - 1.0) / 5.0);
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    // Items are >= 1, but treat gaps < 10 as near-wasted (classic small-item floor).
    if post_residual < 10 {
        score += 120.0;
    } else if post_residual < 20 {
        score += 40.0;
    } else if post_residual < 30 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here: penalize leaving a gap the next item can't use.
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should win only when no open bin offers a decent fit; make empty bins
    // moderately attractive by default but beatable by any reasonable fit.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            // handled above for the fitting bin; here just keep new bin unattractive
            score += 30.0;
        }
    }

    // Slight preference for bins whose residual is close to the mean (keep residuals uniform).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

