            score += (slack - next_waste * 0.55) * 1.05 * (0.5 + progress);
        }
        // 3-step lookahead: extendable chain reward.
        if slack >= (next_item_size as f64) {
            score -= 12.0 + 10.0 * progress;
        }
        // Near-multiple slack promises a longer self-sustaining chain.
        let mult = slack as u32 / next_item_size;
        let mrem = slack as u32 % next_item_size;
        if mult >= 1 && mrem <= 1 {
            score -= (mult.min(4) as f64) * 8.5 * (0.6 + progress);
        }
        if fitting_bins_count > 2 && slack > 10.0 {
            score += (fitting_bins_count as f64 - 2.0).min(4.0) * 3.2;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 27.0 * (0.5 + progress);
        }
        if slack as u32 >= 2 * next_item_size && slack as u32 % (2 * next_item_size) == 0 {
            score -= 16.0 * progress;
        }
        // Two-step tileability — slack that exactly absorbs two more next-size items.
        if next_item_size > 0 && slack as u32 >= 2 * next_item_size && (slack as u32 - 2 * next_item_size) <= 4 {
            score -= 18.0 * (0.5 + progress);
        }
        // Slack tileable by the item size just placed — stream rhythm repeats.
        if item_size > 0 && slack as u32 % item_size <= 1 && slack > 4.0 {
            score -= 10.0 * (0.5 + progress);
        }
        // Tiny tail is near-perfect.
        if slack <= 2 {
            score -= 23.0 * (0.6 + progress);
        }
    }
    // Post-residual too small for the next item: dead space for lookahead.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * (0.5 + 0.24 * gap / capacity_f);
        if gap <= 4.0 && post_f > 0.0 {
            score -= 17.0 * (1.0 - progress);
        }
        if gap <= 2.0 {
            score -= 13.0;
        }
        let rel = gap / (next_item_size as f64).max(1.0);
        score += rel * 27.0 * (0.6 + 0.4 * progress);
        if gap <= 12.0 && progress < 0.6 {
            score -= 7.5 * (1.0 - progress);
        }
        if gap > post_f * 0.6 {
            score += gap * 0.35 * progress;
        }
        // Small gap with a "friendly" post residual (multiple of 5) is recoverable.
        if gap >= 1.0 && gap <= 6.0 && post_residual % 5 <= 2 {
            score -= 5.0 * (1.0 - progress);
        }
        // Large relative gap mid-stream is a fragmentation seed.
        let gap_ratio = gap / (next_item_size as f64).max(1.0);
        if gap_ratio > 0.6 && gap > 14.0 {
            score += gap * 0.22 * (0.5 + progress);
        } else if gap_ratio <= 0.15 && post_f >= 3.0 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Compare post_residual against mean residual: leaving above-average space is good.
    score -= (post_f - mean_residual) * 0.58;

    // Exact closure reward scaled by progress.
    if post_residual == 0 {
        score -= 950.0;
    } else if bin_residual == item_size && bin_residual < bin_capacity {
        score -= 35.0 + 25.0 * progress;
    }

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 118.0;
    }

    // Combined fine-grained fitting + lookahead: bin closes exactly with
    // item + next item — the tightest two-step compaction possible.
    if next_item_size > 0 && bin_residual == item_size + next_item_size {
        score -= 40.0 * (0.6 + progress);
    }
    // Near-closure by item + next item (within 2) is almost as good.
    if next_item_size > 0
        && bin_residual > item_size + next_item_size
        && bin_residual - (item_size + next_item_size) <= 2
    {
        score -= 18.0 * (0.5 + progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 52.0;
        score -= 30.0 * (1.0 - progress);
        let fresh_res = bin_capacity - item_size;
        let fresh_f = fresh_res as f64;
        if next_item_size > 0 && fresh_res >= next_item_size && fresh_res - next_item_size <= 8 {
            score -= 39.0;
        }
        if next_item_size > 0 && (next_item_size as i32 - fresh_res as i32).abs() < 6 {
            score += 15.0 * (1.0 - progress);
        }
        if item_size >= 60 && fresh_res <= 10 {
            score -= 42.0;
        }
        if item_size == bin_capacity {
            score -= 950.0;
        }
        if fitting_bins_count >= 1 && post_residual > 35 {
            score -= 33.0;
        }
        if open_bins_count > 2 && item_size as f64 > capacity_f * 0.8 {
            score += 27.0;
        }
        if fresh_f > 0.0 {
            score += (fresh_f / capacity_f) * 15.0 * progress;
        }
        if fresh_f > 18.0 && fresh_f < capacity_f * 0.45 {
            score += 9.5 * (1.0 - progress);
        }
        // Refuse a fresh bin when some existing bin already yields a tight fit.
        if fitting_bins_count >= 1 {
            if post_residual as f64 <= 5.0 {
                score += 78.0;
            } else if post_f > capacity_f * 0.5 {
                score -= 31.0;
            } else if post_f <= capacity_f * 0.25 {
                score += 23.0 * (0.4 + 0.6 * progress);
            }
        }
        if progress < 0.2 && item_size as f64 > capacity_f * 0.65 {
            score -= 21.0;
        }
        // Fresh-bin residual quality — reusable residuals are cheap to open.
        if next_item_size > 0 {
            let ratio = fresh_f / (next_item_size.max(1) as f64);
            if ratio >= 1.0 && ratio < 2.0 {
                score -= 15.0;
            } else if fresh_f < 8.0 {
                score += 15.0;
            }
            if fresh_res == next_item_size {
                score -= 27.0 * (1.0 - progress);
