        }
    }

    // Waste-proportional penalty scaled by stream progress.
    if post_f > 0.0 {
        score += (post_f / capacity_f) * (1.0 + progress) * (1.0 + 0.5 * progress);
    }

    // Prefer filling bins tightly as the stream progresses.
    score += (post_f / capacity_f) * (1.0 + progress);

    // Slight penalty for spreading across many open bins.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.6;
    }

    // Fragmentation guard: nearly-dead bins are cheap to use up.
    if (bin_residual as f64) < mean_residual * 0.3 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Dead-space entropy guard: residuals near half capacity seed fragmentation.
    let half = capacity_f * 0.5;
    if post_f > half - 6.0 && post_f < half + 6.0 {
        score += 10.0 * (1.0 - progress);
    }

    // Mid-range residuals slightly above half are the worst fragmentation seeds.
    if post_f > half && post_f < half + 12.0 {
        score += 6.0 * progress;
    }

    // Residuals just below half are also poor seeds when many bins are open.
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets — squeeze them hard mid-stream.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.0 * (0.4 + progress);
    }

    // 7..15 band is the next-worst seed zone; mildly discourage late.
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.4 * progress;
    }

    // Quarter/three-quarter dead zones are awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.0 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.0 * (1.0 - progress);
    }

    // Post residual that exactly equals next_item_size plus a tiny
    // remainder still leaves a near-perfect two-step chain — reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let tail = post_residual - next_item_size;
        if tail > 0 && tail <= 2 {
            score -= 22.0 * (0.6 + progress);
        }
    }

    // NEW: dead-space ratio term — compare post residual to the ideal
    // continuation (next item placed in this bin would leave ~0). Bins whose
    // post residual is a small fraction of the next item are near-dead;
    // bins whose post residual exceeds the next item by a large margin are
    // better long-term anchors. Reward the latter, penalize the former.
    if next_item_size > 0 && post_f > 0.0 {
        let dsr = post_f / (next_item_size as f64).max(1.0);
        if dsr < 0.25 && post_residual < next_item_size {
            score += 8.0 * (0.5 + progress);
        } else if dsr >= 2.0 && dsr <= 4.0 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Late-stream zero-tolerance — tighten harder near the end.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.45 * (progress - 0.72) * 4.0;
    }

    // Late-stream tightening.
    score *= 1.0 + 0.28 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 && post_residual > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // leftover after chaining two items
            let chain_left = post_residual - next_item_size;
            score -= 50.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
            if chain_left < 10 {
                score -= 100.0; // near-triple fill
            }
        } else {
            // next item can't fit here: penalize dead space
            score += 30.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.5;

    // Last-chance bin bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize leaving very small unusable gaps (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Slight preference for keeping a fresh empty bin in reserve early on
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is best).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins where the lookahead item also fits the new residual (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
    }
    // Penalize leaving a residual that is small but too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 7.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }
    // Many alternatives: mild penalty to prefer keeping flexible bins for later.
    if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Prefer filling bins that are already mostly used (low residual relative to mean).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Time horizon: early in the stream, be more conservative about fragmenting space;
    // late in the stream, just close out bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate handling: opening a fresh bin is only attractive for large items
    // or when this would otherwise be a very poor fit.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 30.0 - 20.0 * large_item;
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        // Late in stream, avoid opening bins that will barely be used.
        new_bin_score += 15.0 * progress;
        score = score.min(new_bin_score) * 0.5 + new_bin_score * 0.5;
        // Ensure new bin is not chosen when a decent open-bin fit exists.
        if fitting_bins_count > 0 && post_residual + item_size <= bin_capacity {
            let best_possible = post_residual as f64;
            if best_possible < 15.0 {
                score += 20.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual, non-linearly coupled with stream progress.
    // Early on, prefer tight fills (minimize post_residual strongly);
    // later, dead space matters even more, so penalize quadratically.
    let mut score = pr * (1.0 + 1.5 * pr_norm * pr_norm);
    score += 4.0 * progress * pr_norm * pr_norm * cap;

    // Reward using a bin whose residual would otherwise be stranded:
    // last-chance bins get a strong bonus, smoothly scaled by fit tightness.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * (1.0 - pr_norm);
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // reward strongly; if post_residual is just barely too small for the
    // next item, penalize (wasted near-fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            score -= 8.0 * (1.0 - diff / cap);
        } else {
            score += 5.0 * (-diff / cap);
        }
    }

    // Smooth penalty when bin residual deviates from the mean residual
    // (favor bins with unusually low residual, i.e. nearly full ones).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild pressure against opening many bins early.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline, penalized unless item is
    // large relative to capacity (better to start fresh for big items).
    if bin_residual == bin_capacity {
        score = cap * 0.6 - item_size as f64 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: perfect two-item fill is ideal.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0; // bin will be exactly full after next item
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits: mild reward scaled by tightness.
        score -= 8.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space the next item cannot use: penalize proportionally,
        // harsher when the dead space is tiny (unusable sliver).
        let dead = post_residual as f64;
        score += 10.0 + 30.0 * (1.0 - dead / 100.0);
    }

    // Prefer bins whose residual is below the mean (tighter bins get packed first),
    // keeping loose bins available for larger future items.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so we only open new bins when
    // no open bin offers a genuinely good fit.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Late in the stream, consolidation matters more: tighten selection.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: relative waste in the bin.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bins have poor fits
    // or the item fits badly everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fit_ratio < 0.5 {
            score += 25.0; // discourage opening new bin on a good fit
        } else {
            score -= 8.0; // encourage fresh bin when fit is poor
        }
        // Early in the stream, keep flexibility: slightly discourage new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits this bin's post-residual, reward;
    // if next item is large and this bin would be left with tiny residual, penalize.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 4.0;
        } else if post_residual > 0 && (next_item_size as f64) > (post_residual as f64) {
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Global state coupling: many open bins with high mean residual →
    // prefer filling existing bins over opening new ones.
    if !is_new_bin {
        score -= 0.02 * mean_residual;
        score += 0.5 * open_bins_count as f64;
    } else {
        score += 0.05 * mean_residual;
    }

    // Mild noise-free tiebreak by exact post residual ordering.
    score += post_residual as f64 / 1000.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with a smooth non-linear polynomial coupling
    // to stream progress. Late in the stream, tight fits are weighted more heavily.
    let mut score = pr * (1.0 + 2.0 * progress * progress) + cap * 6.0 * progress * norm_pr * norm_pr;

    // Dead-space penalty: residuals too small to fit typical future items.
    let dead_zone = (norm_pr - 0.12).max(0.0) * (0.12 - norm_pr).max(0.0);
    score += 40.0 * dead_zone;

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: reward if next item fits into post-residual (smooth coupling).
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as f64;
        score -= 8.0 * fits_next * (1.0 + progress);
        // Mild penalty for post-residuals that just barely miss the next item.
        let miss = ((next_item_size as f64 - pr) / cap).max(0.0);
        score += 15.0 * miss * miss * cap;
    }

    // Crowd penalty: with many open bins, discourage spreading into loose fits.
    let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / cap);
    score += 2.0 * crowd * norm_pr * (1.0 - progress * 0.5);

    // New-bin candidate: make it moderately attractive early, less so late.
    if bin_residual == bin_capacity {
        score = cap * (1.2 - 0.7 * progress) + 10.0 * progress;
    }

    score
}

