    }

    // Prefer bins with below-average residual (consolidate emptiness)
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 0.05 * residual_gap;

    // Mild pressure against spreading across many open bins
    score += 0.01 * open_bins_count as f64 * pr_norm;

    // New-bin candidate handling: make an empty bin attractive only when the fit is poor
    // or late in the stream with large leftovers; otherwise prefer reusing open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying with progress and poor reuse potential
        let reuse_potential = pr_norm; // = 1.0 for empty bin
        score += 15.0 * (1.0 - 0.5 * progress) - 5.0 * (1.0 - item_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quantization.
    // Residuals in [0..10) are near-perfect fits; [10..30) usable; >=30 wasteful.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else if post_residual < 10 {
        score -= 80.0;
    } else if post_residual < 30 {
        score -= 15.0;
    } else {
        score += (post_residual as f64 - 30.0) * 0.5; // penalize large dead space
    }

    // Harmonic pairing: does the NEXT item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly-ish: strong reward, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.4;
        } else {
            // next item breaks this bin: mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.3;
        }
    }

    // Last-chance logic: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0; // strongly prefer using the sole fitting bin
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 60.0;
        // less costly to open a bin early in the stream or when many bins open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // if existing bins are fragmented (high mean residual but item barely fits),
        // opening fresh is more attractive
        if post_residual > 40 {
            score -= 20.0;
        }
        // perfect-size harmonic class: opening a bin whose residual matches
        // common item sizes (multiples of 10) is attractive
        if bin_capacity % 10 == 0 {
            score -= 5.0;
        }
    } else if post_residual < 10 && next_item_size > 0 && post_residual >= next_item_size {
        // tight chain fit in an existing bin: extra reward
        score -= 10.0;
    }

    // Congestion: with many open bins, favor consolidating into existing ones.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Small tie-breaker on exact post residual mod classes to keep determinism.
    let class = post_residual % 10;
    score += class as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: post_residual in a "dead zone" (too small
    // for typical items) is wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 2.0;
    }
    // Mildly penalize mid-range gaps that only fit small items.
    else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins; penalize opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 20.0 * progress + (open_bins_count as f64).sqrt() * 3.0;
    } else {
        // Last-chance bonus: if this is the only bin that fits, avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Reward filling bins tighter than the current mean residual.
        if (post_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Lookahead: if the next item fits in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item almost fits (small shortfall), slight penalty for blocking.
    else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: perfect two-item fill is ideal.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0; // bin will be exactly full after next item
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits: mild reward scaled by tightness.
        score -= 8.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space the next item cannot use: penalize proportionally,
        // harsher when the dead space is tiny (unusable sliver).
        let dead = post_residual as f64;
        score += 10.0 + 30.0 * (1.0 - dead / 100.0);
    }

    // Prefer bins whose residual is below the mean (tighter bins get packed first),
    // keeping loose bins available for larger future items.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so we only open new bins when
    // no open bin offers a genuinely good fit.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Late in the stream, consolidation matters more: tighten selection.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize high post_residual quadratically.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is poor
    // everywhere else. A fresh bin has residual == capacity, so its post_residual
    // is large; add a fixed penalty that tight fits elsewhere can overcome.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If the next item is large, a fresh bin is more attractive (keeps
        // large slack bins free for big items).
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: reward leaving residual that can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 8.0 * (nx / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize wasted capacity.
            let waste = (nx - post_residual as f64).min(nx);
            score += 0.15 * waste;
        }
    }

    // Global slack pressure: when open bins are collectively loose (high mean
    // residual), discourage spreading into new bins; encourage filling loose ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual as f64 > mean_residual {
        score += 0.05 * (bin_residual as f64 - mean_residual) * (1.0 - 0.5 * progress);
    } else {
        score -= 0.05 * (mean_residual - bin_residual as f64);
    }

    // Late-stream consolidation: as the stream ends, prefer bins that end
    // with very small residuals (near-perfect packing).
    score -= 12.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Mild penalty on bin count growth pressure.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth polynomial base: penalize post_residual, with curvature growing over stream progress
    let poly = norm_post * (1.0 + 2.0 * progress * norm_post + 1.5 * progress * norm_post * norm_post);

    // Interaction: large leftover relative to mean residual is dead space
    let dead = if mean_residual > 0.0 {
        let ratio = norm_post - (mean_residual / cap);
        ratio * ratio * (0.5 + progress)
    } else {
        0.0
    };

    // Lookahead coupling: reward leaving room for next item, smoothly
    let nxt = next_item_size as f64 / cap;
    let look = if next_item_size > 0 {
        -0.6 * progress * nxt * (1.0 - norm_post) * (1.0 - (post - nxt).abs())
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor using the only fitting bin
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -1.5 * (1.0 + progress)
    } else {
        0.0
    };

    // New-bin candidate penalty scaled by progress and open bins
    let new_bin = if bin_residual == bin_capacity {
        0.8 + progress * 0.7 + (open_bins_count as f64 * 0.05)
    } else {
        0.0
    };

    // Slight reward for tight fits (small post_residual)
    let tight = -0.3 * (1.0 - norm_post) * (1.0 - norm_post);

    score = poly * cap * 0.01 + dead + look + last_chance + new_bin + tight;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it land in?
    // Bands: [0], (0,10], (10,25], (25,50], (50,100) — small residuals are "dead space".
    let band = if post_residual == 0 { 0u32 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 25 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };

    // Penalize dead space non-linearly; tiny residuals are nearly worthless.
    let dead_penalty = match band {
        0 => -40.0,               // perfect fit: strong reward
        1 => 30.0,                // nearly dead space
        2 => 8.0,
        3 => -2.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Integer-division harmonic: post_residual divisible by small "chunk" classes (10/20)
    // leaves room for typical small items — reward reusability.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        // Post residual exactly matching a common small-item class is valuable.
        if post_residual >= 10 && post_residual <= 30 { score -= 4.0; }
    }

    // Lookahead coupling: if the next item fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (next_item_size as f64);
        // Exact two-item closure: item + next fills the bin completely.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize leaving mid-size gaps.
        score += 3.0;
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual <= 15 { score -= 10.0; }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when the current item is large or open bins are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins are open
        // (fragmentation) or the item is large.
        score = 55.0
            - 0.25 * (open_bins_count as f64)
            + 0.35 * (item_size as f64)
            - (mean_residual / bin_capacity as f64) * 20.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Small items should almost never open fresh bins.
        if item_size <= 20 { score += 25.0; }
    }

    // Mild global pressure: when mean residual is low, tighten packing (favor small scores
    // for tight fits everywhere by scaling).
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.06;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item leaves a remainder; penalize large leftovers
            let rem = post_residual - next_item_size;
            score += rem as f64 * 0.5;
        } else {
            // next item cannot fit here; small penalty scaled by gap
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.3;
        }
    }

    // Compare post_residual against mean residual of open bins
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        score += 150.0;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 100.0;
        }
    }

    // Late in stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.2 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize small post-residuals that are too small for typical future items
    // (dead space below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
        // If next item is large, prefer leaving large contiguous space.
        if next_item_size >= 60 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 45.0 * pressure;
        // Late in stream, opening new bins is cheaper than fragmenting many bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Global state: when many bins are open with high mean residual, discourage
    // spreading items into already-loose bins; prefer consolidating.
    let residual_pressure = mean_residual / bin_capacity as f64;
    if open_bins_count > 2 && residual_pressure > 0.5 {
        score += 10.0 * residual_pressure * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild time horizon scaling: early on, be slightly greedy toward tight fits
    // to establish good structure; later, prioritize keeping bins usable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * tightness;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with smooth polynomial deepening over stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth coupling: squared normalized post-residual penalizes dead space more as stream advances
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits relative to capacity
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Smooth penalty when many open bins already exist (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * (1.0 + progress);

    // Mean residual coupling: penalize placing into bins far from the fleet mean
    score += 0.15 * (mean_residual - pr).abs();

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score -= 8.0 * (gap / cap) * (1.0 - progress);
        // Penalize post-residual that is small but nonzero relative to next item
        let waste = (next_item_size as f64 - pr).max(0.0);
        score += 0.2 * waste * (0.5 + progress);
    }

    // New-bin candidate: mild penalty so it only wins when open bins are genuinely bad
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress) - 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: classify dead space by size class ---
    // Classes (of 100-capacity): [0..10) tiny (excellent), [10..20) good,
    // [20..40) medium, [40..70) poor, [70..100) terrible.
    let class: f64 = if post_residual < 10 { 0.0 }
        else if post_residual < 20 { 1.0 }
        else if post_residual < 40 { 2.0 }
        else if post_residual < 70 { 3.0 }
        else { 4.0 };
    score += class * 12.0;

    // Perfect-fit reward: residual exactly 0
    if post_residual == 0 {
        score -= 60.0;
    }

    // Divisibility / modulo structure of post_residual vs capacity fractions
    // Residuals that are multiples of common item sizes (10,20,25,50) are reusable.
    if post_residual % 10 == 0 { score -= 8.0; }
    if post_residual % 25 == 0 { score -= 4.0; }
    if post_residual % 50 == 0 { score -= 4.0; }

    // Lookahead compatibility: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Good: next item can land here too; reward proportionally
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize wasted future capacity proportionally to overshoot
            let waste = (next_item_size - post_residual) as f64;
            score += 0.25 * waste;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we only open new bins
    // when existing bins fit badly, but keep it competitive for large items.
    if bin_residual == bin_capacity {
        score += 35.0 + 0.15 * (post_residual as f64);
        // If item is huge relative to capacity, opening fresh is fine
        if item_size * 4 >= bin_capacity * 3 {
            score -= 25.0;
        }
    }

    // Mean residual coupling: when open bins are already loose (high mean residual),
    // avoid adding more dead space; when bins are tight, filling is fine.
    score += 0.10 * (mean_residual - post_residual as f64).abs();

    // Stream progression: early on, be greedy about tight fits; later, allow
    // slightly looser packing since many bins are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - class / 4.0);

    // Small penalty per open bin to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // Penalize post_residual that is too small to ever hold a meaningful item.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: extremely costly dead space.
            score += 40.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 12.0;
        }
    } else {
        // Perfect fill: reward strongly.
        score -= 60.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += 8.0 * tightness;

    // Open-bin pressure: discourage opening new bins when many are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin; grows with open bin count.
        score += 30.0 + 4.0 * open_bins_count as f64;
        // But if this bin is the last chance for the item, opening a new bin
        // is necessary: relieve the penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the item nearly fills a fresh bin, opening is attractive.
        if item_size >= 70 {
            score -= 25.0;
        }
    } else if fitting_bins_count == 1 {
        // This is the only bin that can fit the item: strongly favor using it
        // to avoid opening a new bin.
        score -= 35.0;
    }

    // Lookahead: if the next item fits into the resulting post_residual,
    // reward this placement (chains two items into one bin).
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
        // Extra reward for a near-perfect lookahead chain.
        if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (consume the tighter bins first, keep loose bins flexible).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    } else {
        score += 0.15 * (res - mean_residual);
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over spreading out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: bin exactly absorbs item + next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near-perfect lookahead match (small slack for next item).
    else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        score -= 120.0;
    }
    // Post-residual too small for the next item: dead space for lookahead.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Compare post_residual against mean residual: leaving above-average space is good.
    score -= (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize new-bin candidate mildly so open bins with decent fit win;
    // but allow opening a new bin when the item is large and fits would waste much space.
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size >= 60 && bin_residual - item_size <= 10 {
            score -= 30.0;
        }
    }

    // Prefer filling bins tightly as the stream progresses (endgame tightness).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 / bin_capacity as f64) * (1.0 + progress);

    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if bin_residual >= next_item_size {
            // This bin could serve the next item better; slight penalty.
            score += 8.0;
        }
        // Perfect pairing: item + next item exactly fill the bin.
        if item_size + next_item_size == bin_residual {
            score -= 35.0;
        }
    }

    // Time horizon: early in stream, be pickier (prefer tight fits / new bins
    // for large items); late in stream, just fill anything.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Global state: many open bins with high mean residual -> discourage
    // opening new bins, encourage consolidating into existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins already hold lots of space.
        score += 0.3 * open_bins_count as f64 + 0.2 * mean_residual;
        // But allow new bins early when item is large and fits would be sloppy.
        if item_size > 50 && progress < 0.5 {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins when mean residual is high (fragmentation risk).
        score -= 0.1 * mean_residual;
    }

    // Mild penalty per open bin to discourage sprawl when placing in open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling: post_residual scaled by stream progress
    score += 6.0 * (pr / cap) * (pr / cap) * (progress - 0.5);

    // Penalize residual that is too small to be useful (dead space), smoothly
    let dead = ((20.0 - pr) / 20.0).max(0.0);
    score += 12.0 * dead * dead;

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= 10.0 * (1.0 - pr / cap) * progress * progress;

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that can still fit the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 4.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for leaving residual far from mean residual (fragmentation)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: make empty bin attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (mean_residual / cap) + 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction bands.
    // Small post_residual is good UNLESS it's unusable dead space (< smallest useful size).
    let dead = post_residual < 10u32.min(bin_capacity / 10);
    if dead {
        score += 60.0; // waste penalty: dead space band
    } else {
        // Reward tight fits: classify post_residual by harmonic bands of capacity
        let band = post_residual * 4 / bin_capacity; // 0..3 harmonic class
        score -= match band {
            0 => 25.0, // nearly full: excellent
            1 => 12.0, // quarter-ish residual
            2 => 4.0,
            _ => 0.0,
        };
        // Fine-grained modulo coupling: residual divisible by common item sizes
        // means future items can tile the leftover space exactly.
        if post_residual > 0 {
            let r = post_residual;
            if r % 10 == 0 { score -= 6.0; }
            else if r % 5 == 0 { score -= 3.0; }
        }
    }

    // Lookahead: strongly reward if next item fits in the post_residual (chaining),
    // with extra weight when next item is large (hard to place later).
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        let big_next = if next_item_size > bin_capacity / 2 { 1.5 } else { 1.0 };
        score -= (8.0 + 20.0 * (1.0 - tightness / bin_capacity as f64)) * big_next;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // leftover can't host the next item: penalize proportionally to how much
        // of the leftover is stranded, unless it's essentially full.
        if post_residual > 0 && post_residual < bin_capacity / 4 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: residual == capacity. Opening a new bin is only good when
    // the current item fits poorly everywhere (high post_residual in any open bin)
    // or few bins fit. Penalize the empty bin otherwise; scale with stream progress
    // and current bin count (early on, keep bin count low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 15.0 + 20.0 * (1.0 - progress);
        score += base + 2.0 * open_bins_count as f64;
        // If the item is large and would leave a big hole in any open bin,
        // a fresh bin is more attractive: partially offset the penalty.
        if item_size > bin_capacity / 2 {
            score -= 18.0;
        }
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Mild tie-break: prefer bins whose residual is above the mean (keep tight bins
    // tight, use roomy bins for awkward items).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest conceivable item (<= 10) are wasted space -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    }
    // "Awkward gap" band: residuals that likely cannot fit future items
    // (small but nonzero) get a graded penalty.
    if post_residual > 0 && post_residual < 25 {
        score += 25.0 * (1.0 - post_residual as f64 / 25.0);
    }
    // Perfect or near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward using a bin that fits the item exactly with the lookahead too:
    // if next item can still fit in post_residual, this is a good chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This placement strands a gap smaller than the next item.
        score += 12.0;
    }

    // Last-chance pressure: if this is the ONLY bin that fits, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 8.0 * (open_bins_count as f64).sqrt() + 5.0;
        // Exception: if the current item leaves an awkward gap in every
        // plausible bin, opening fresh may be fine — soften penalty when
        // the item is large relative to capacity.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 12.0;
        }
    }

    // Mild global balance: prefer bins whose residual is below the mean
    // (fill the emptiest-fitting bins first keeps many usable bins open).
    if !new_bin_candidate {
        let res = post_residual as f64;
        if res < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0 * (res - mean_residual) / bin_capacity as f64;
        }
    }

    // Late-stream tightening: as the stream progresses, be stricter about
    // dead space since fewer chances remain to recover wasted capacity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    if next_item_size > 0 {
        // Perfect 2-step lookahead match: this bin's post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too; reward closeness of the match.
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (-slack / 15.0).exp();
        } else {
            // Next item won't fit here; penalize proportionally to the gap,
            // since the leftover is more likely to be dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / 25.0).min(2.0);
        }
    } else {
        // Last item: minimize final waste aggressively.
        score += 10.0;
    }

    // Compare against mean residual of open bins: prefer bins tighter than average.
    let dev = (bin_residual as f64) - mean_residual;
    score -= 2.5 * (dev / 50.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize creating very small unusable residuals (dead space), unless it's a
    // perfect lookahead match (already heavily rewarded).
    if post_residual > 0 && post_residual < 10 && !(next_item_size > 0 && post_residual == next_item_size) {
        score += 14.0;
    }

    // New-bin candidate: only attractive when no open bin is a good home
    // (i.e., many fitting bins but poor fits, or lookahead mismatch everywhere).
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 8.0 };
        score += 20.0 + poor_fit_penalty - 3.0 * (fitting_bins_count as f64);
        // Late in the stream, opening new bins is more acceptable.
        score -= 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild preference to keep number of open bins low early on.
    score += 0.3 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in fill ratio).
    let tightness = (bin_residual - post_residual) as f64 / bin_residual as f64;
    score -= 40.0 * tightness * tightness;

    // Penalize small dead space that nothing can use (post_residual < 10).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect pair
        } else if next_item_size <= post_residual {
            score -= 20.0 * (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            score += 10.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Global state: prefer filling bins when many bins are open (consolidate).
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= 15.0 * pressure * tightness;

    // Time horizon: early in the stream, be more willing to open new bins
    // (spread items); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0;
    score -= progress * 12.0 * tightness;

    // Mean residual coupling: if this bin's residual is far above mean,
    // it's a "loose" bin — mildly discourage; below mean, encourage filling it.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff;

    // New-bin candidate: bias against opening a new bin unless the item
    // is large relative to capacity and current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 30.0 - 25.0 * fragmentation - 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: post residual, with non-linear shrink for very small dead space.
    let mut score = pr;

    // Smooth polynomial coupling: tiny post-residuals are heavily rewarded,
    // large post-residuals mildly penalized, modulated by stream progress.
    let tightness = (1.0 - norm_post).max(0.0);
    score -= 60.0 * (1.0 - norm_post).powi(4) * (0.5 + 0.5 * progress);

    // Penalize residual that is unusable for typical future items,
    // penalized more strongly as the stream progresses.
    let dead = (1.0 - norm_post) * norm_post; // peaks at 0.25 residual fraction
    score += 40.0 * dead * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 55.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward if next item can fit the post-residual.
    if next_item_size > 0 {
        let fits_next = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let near = 1.0 - ((next_item_size as f64 - pr).abs() / cap);
        score -= 25.0 * fits_next * near.max(0.0);
        // Penalize leaving residual just barely too small for next item.
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 && gap <= 20.0 {
            score += 12.0 * (1.0 - gap / 20.0);
        }
    }

    // Mild penalty for spreading across many bins when residuals are high.
    let mean_norm = mean_residual / cap;
    score += 8.0 * (open_bins_count as f64).ln().max(0.0) * mean_norm * (1.0 - progress);

    // Early-stream: favor consolidation into existing bins.
    score -= 15.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover into usable bands.
    // Class A: post_residual >= 40 (can host most future items) — mild penalty already in base.
    // Class B: 20..40 — moderately usable.
    // Class C: 1..20 — dead space risk, penalize.
    let pr = post_residual;
    if pr > 0 && pr < 20 {
        // Dead space zone; worse the smaller it is (unusable fraction).
        score += (20 - pr) as f64 * 2.5;
    } else if pr >= 20 && pr < 40 {
        score -= 5.0;
    } else if pr >= 40 {
        // Large leftover keeps bin flexible.
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size <= pr {
            // Next fits, but leaves its own residue — reward proportional to tightness.
            let nxt_left = pr - next_item_size;
            if nxt_left < 20 {
                score -= 60.0 - (nxt_left as f64) * 2.0;
            } else {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: slight penalty for trapping the stream.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
        if pr > 0 && pr < 20 {
            score -= 10.0; // still prefer using it over a new bin
        }
    }

    // New-bin candidate handling: empty bin gets baseline near cap minus
    // flexibility bonus, so it wins only when all open fits are bad.
    if bin_residual == bin_capacity {
        score = cap - 12.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Slight tilt: fresh bin can host next item too.
            score -= 3.0;
        }
    }

    // Stream progression: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr > 0 {
        score -= progress * (pr.min(30) as f64) * 0.3;
    }

    // Mean residual context: when open bins are already slack, penalize
    // adding more slack (fragmentation pressure).
    if mean_residual > cap * 0.5 && pr > 30 {
        score += (mean_residual - cap * 0.5) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else if post_residual < 10 {
        score -= 80.0;
    } else if post_residual < 30 {
        score -= 15.0;
    } else {
        score += (post_residual as f64 - 30.0) * 0.5;
    }

    // Harmonic pairing: does the NEXT item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.4;
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.3;
        }
    }

    // MUTATION: two-item lookahead coupling. If the next item fits the post
    // residual *snugly* (slack under 5), this bin is a chain anchor; reward it
    // extra so we don't abandon a bin that will absorb the upcoming item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
