        let q = capacity_f * 0.25;
        let m = (post_f / q).round();
        if m >= 1.0 && (post_f - m * q).abs() <= 1.0 {
            score -= 6.0;
        }
    }

    // Lookahead trade-off: if next item cannot fit anywhere else (fitting
    // scarcity proxy via mean residual), keep bins whose post_residual
    // accommodates it.
    if next_item_size > 0 && post_residual >= next_item_size && mean_residual < next_item_size as f64 {
        score -= 12.0;
    }

    // Penalize post-residuals awkwardly just above the next item
