        }
        // NEW: slack that is itself nearly divisible by the next item
        // promises a longer chain — reward proportionally.
        let slack_rem = slack as u32 % next_item_size;
        if slack_rem <= 1 && slack >= next_item_size as f64 {
            score -= 8.0 * (0.6 + progress);
