    let half = capacity_f * 0.5;
    if post_f > half - 6.0 && post_f < half + 6.0 {
        score += 10.0 * (1.0 - progress);
    }

    // Mid-range residuals slightly above half are the worst fragmentation seeds.
    if post_f > half && post_f < half + 12.0 {
        score += 6.0 * progress;
    }

    // Residuals just below half are also poor seeds when many bins are open.
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
