    // Prefer filling bins tightly as the stream progresses.
    score += (post_f / capacity_f) * (1.0 + progress);

    // Slight penalty for spreading across many open bins.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.6;
    }

    // Fragmentation guard: nearly-dead bins are cheap to use up.
    if (bin_residual as f64) < mean_residual * 0.3 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Dead-space entropy guard: residuals near half capacity seed fragmentation.
    let half = capacity_f * 0.5;
    if post_f > half - 6.0 && post_f < half + 6.0 {
        score += 10.0 * (1.0 - progress);
    }

    // Mid-range residuals slightly above half are the worst fragmentation seeds.
    if post_f > half && post_f < half + 12.0 {
        score += 6.0 * progress;
    }

    // Residuals just below half are also poor seeds when many bins are open.
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets — squeeze them hard mid-stream.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.0 * (0.4 + progress);
    }

    // 7..15 band is the next-worst seed zone; mildly discourage late.
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.4 * progress;
    }

    // Quarter/three-quarter dead zones are awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.0 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.0 * (1.0 - progress);
    }

    // Post residual that exactly equals next_item_size plus a tiny
    // remainder still leaves a near-perfect two-step chain — reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let tail = post_residual - next_item_size;
        if tail > 0 && tail <= 2 {
            score -= 22.0 * (0.6 + progress);
        }
    }

    // Dead-space ratio vs. open-bin pool — when few bins remain
    // usable (fitting_bins_count small) and post residual is large,
    // this bin is the last compaction chance; reward using it fully.
    if fitting_bins_count <= 2 && post_f > capacity_f * 0.3 {
        score -= (post_f / capacity_f) * 26.0 * (0.4 + progress);
    }

    // Late-stream zero-tolerance — tighten harder near the end.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.45 * (progress - 0.72) * 4.0;
    }

    // Late-stream tightening.
    score *= 1.0 + 0.28 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

