        if depth >= 3 {
            score -= (depth.min(6) as f64) * 5.0 * (0.5 + progress);
        }
        // Dead-space ratio refinement — penalize slack that exceeds the
        // fraction of capacity the next item would otherwise leave behind.
        let next_waste = capacity_f - (next_item_size as f64);
        if slack > next_waste * 0.6 {
            score += (slack - next_waste * 0.6) * 0.9 * (0.5 + progress);
        }
        // 3-step lookahead — extendable chain reward.
        if slack >= (next_item_size as f64) {
            score -= 12.0 + 10.0 * progress;
        }
        // Near-multiple slack promises a longer self-sustaining chain.
        let mult = slack as u32 / next_item_size;
        let mrem = slack as u32 % next_item_size;
        if mult >= 1 && mrem <= 1 {
            score -= (mult.min(4) as f64) * 8.0 * (0.6 + progress);
        }
        // Exact 2x-next residual is a golden two-step chain.
        if post_residual == 2 * next_item_size {
            score -= 26.0 * (0.5 + progress);
        }
        // When several bins can fit the item, reward only the tightest
        // chain candidates to avoid spreading lookahead rewards too broadly.
        if fitting_bins_count > 2 && slack > 10.0 {
            score += (fitting_bins_count as f64 - 2.0).min(4.0) * 3.0;
        }
        // NEW: two-step exact closure — after consuming next item, the remaining
        // slack equals the item again, promising a perfect 3-item closure.
        if slack as u32 == next_item_size * 2 {
            score -= 18.0 * (0.4 + progress);
        }
        // NEW: slack smaller than next item means dead space after the lookahead
        // step — penalize proportionally to how unusable the remainder is.
        if slack < 1.0 {
            score -= 10.0;
        }
    }
    // Post-residual too small for the next item: dead space for lookahead.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * (0.48 + 0.24 * gap / capacity_f);
        if gap <= 4.0 && post_f > 0.0 {
            score -= 16.0 * (1.0 - progress);
        }
        if gap <= 2.0 {
            score -= 12.0;
        }
        // Gap relative to item size — large item with tiny gap nearly closes.
        let rel = gap / (next_item_size as f64).max(1.0);
        score += rel * 26.0 * (0.6 + 0.4 * progress);
        // Small gaps are recoverable by common small items mid-stream.
        if gap <= 12.0 && progress < 0.6 {
            score -= 7.0 * (1.0 - progress);
        }
        // Dead space dominating the residual is worse late.
        if gap > post_f * 0.6 {
            score += gap * 0.35 * progress;
        }
        // NEW: post-residual that matches a likely small filler (<= 8) is still
        // recoverable; soften the dead-space penalty mid-stream.
        if post_residual <= 8 && post_residual > 0 && progress < 0.7 {
            score -= 5.0 + 3.0 * (1.0 - progress);
        }
    }

    // Compare post_residual against mean residual: leaving above-average space is good.
    score -= (post_f - mean_residual) * 0.55;

    // Exact closure reward scaled by progress.
    if post_residual == 0 {
        score -= 950.0;
    } else if bin_residual == item_size && bin_residual < bin_capacity {
        score -= 34.0 + 24.0 * progress;
    }

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 115.0;
    }

    // NEW: when exactly two bins fit, break the tie toward the one whose
    // post-residual best matches the next item (or zero).
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual > 0 {
        let d = (post_residual as i32 - next_item_size as i32).abs();
        if d <= 4 {
            score -= (5.0 - d as f64) * 6.0;
        }
    }

    // New-bin candidate handling: penalize mildly, allow when fits waste much space.
    if bin_residual == bin_capacity {
        score += 50.0;
        score -= 30.0 * (1.0 - progress);
        let fresh_res = bin_capacity - item_size;
        if next_item_size > 0 && fresh_res >= next_item_size && fresh_res - next_item_size <= 8 {
            score -= 38.0;
        }
        if next_item_size > 0 && (next_item_size as i32 - fresh_res as i32).abs() < 6 {
            score += 14.0 * (1.0 - progress);
        }
        if item_size >= 60 && fresh_res <= 10 {
            score -= 40.0;
        }
        if item_size == bin_capacity {
            score -= 950.0;
        }
        if fitting_bins_count >= 1 && post_residual > 35 {
            score -= 32.0;
        }
        if open_bins_count > 2 && item_f > capacity_f * 0.8 {
            score += 26.0;
        }
        let fresh_f = fresh_res as f64;
        if fresh_f > 0.0 {
            score += (fresh_f / capacity_f) * 15.0 * progress;
        }
        if fresh_f > 18.0 && fresh_f < capacity_f * 0.45 {
            score += 9.0 * (1.0 - progress);
        }
        // Refuse a fresh bin when some existing bin already yields a tight fit.
        if fitting_bins_count >= 1 {
            if post_residual as f64 <= 5 {
                score += 75.0;
            } else if post_f > capacity_f * 0.5 {
                score -= 30.0;
            } else if post_f <= capacity_f * 0.25 {
                score += 22.0 * (0.4 + 0.6 * progress);
            }
        }
        // Early-stream large items are better seeded into a fresh bin.
        if progress < 0.2 && item_f > capacity_f * 0.65 {
            score -= 20.0;
        }
        // Fresh-bin waste quality — reusable residuals are cheap to open.
        if next_item_size > 0 {
            let ratio = fresh_f / (next_item_size.max(1) as f64);
            if ratio >= 1.0 && ratio < 2.0 {
                score -= 14.0;
            } else if fresh_f < 8.0 {
                score += 14.0;
            }
            // Fresh residual exactly matching next item is a great seed.
            if fresh_res == next_item_size {
                score -= 26.0 * (1.0 - progress);
            }
            // Near-multiple fresh residual seeds a long chain.
            let fmult = fresh_res / next_item_size;
            let frem = fresh_res % next_item_size;
            if fmult >= 2 && frem <= 2 {
                score -= (fmult.min(5) as f64) * 5.0;
            }
            // NEW: fresh residual just below next item is pure dead space — refuse.
            if fresh_res > 0 && fresh_res < next_item_size {
                score += 12.0 + 0.2 * (next_item_size - fresh_res) as f64;
            }
        }
        // Never open a fresh bin when the item nearly fills an existing bin exactly.
        if fitting_bins_count >= 1 && bin_capacity - item_size <= 2 {
            score += 48.0;
        }
        // Late-stream fresh bins must be nearly self-closing; otherwise refuse.
        if progress > 0.7 && fresh_f > 0.0 && fresh_f < next_item_size.max(1) as f64 {
            score += 30.0 * progress;
        }
        // Refuse fresh bins late unless the residual is very tight or tiny.
        if progress > 0.75 && fresh_f >= 12.0 {
            score += 18.0 * (progress - 0.75) * 4.0;
        }
        // Late fragmentation guard: many open bins late means refuse harder.
        if progress > 0.8 && open_bins_count > 6 && fresh_f > 4.0 {
            score += 20.0 * progress;
        }
        // Awkward fractional multiples seed fragmentation.
        if next_item_size > 0 {
            let ratio = fresh_f / (next_item_size as f64).max(1.0);
            let frac = ratio - ratio.floor();
            if ratio >= 1.0 && frac > 0.05 && frac < 0.4 {
                score += 10.0 * (0.5 + progress);
            }
        }
        // NEW: opening a fresh bin is more acceptable when few bins are open
        // early — residual variance stays low and future fits remain flexible.
        if open_bins_count <= 2 && progress < 0.3 {
            score -= 8.0 * (1.0 - progress);
        }
        // NEW: refuse fresh bins when the current bin set has small residuals
        // that this item could still absorb well.
        if fitting_bins_count >= 1 && post_f > 0.0 && post_f <= item_f * 0.35 {
            score += 20.0;
        }
    }

    // Waste-proportional penalty scaled by stream progress.
    if post_f > 0.0 {
        score += (post_f / capacity_f) * (1.0 + progress) * (1.0 + 0.5 * progress);
    }

    // Prefer filling bins tightly as the stream progresses.
    score += (post_f / capacity_f) * (1.0 + progress);

    // Slight penalty for spreading across many open bins.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.6;
    }

    // Fragmentation guard: nearly-dead bins are cheap to use up.
    if (bin_residual as f64) < mean_residual * 0.3 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Dead-space entropy guard: residuals near half capacity seed fragmentation.
    let half = capacity_f * 0.5;
    if post_f > half - 6.0 && post_f < half + 6.0 {
        score += 10.0 * (1.0 - progress);
    }

    // Mid-range residuals slightly above half are the worst fragmentation seeds.
    if post_f > half && post_f < half + 12.0 {
        score += 6.0 * progress;
    }

    // Residuals just below half are also poor seeds when many bins are open.
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets — squeeze hard mid-stream.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.0 * (0.4 + progress);
    }

    // 7..15 band is the next-worst seed zone; mildly discourage late.
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.4 * progress;
    }

    // Quarter/three-quarter dead zones are awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.0 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.0 * (1.0 - progress);
    }

    // Two-step chain with tiny tail is near-perfect — reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let tail = post_residual - next_item_size;
        if tail > 0 && tail <= 2 {
            score -= 22.0 * (0.6 + progress);
        }
    }

    // NEW: large items (>60% capacity) should prefer bins whose post-residual
    // is minimal, since leftovers from big items are hard to reuse.
    if item_f > capacity_f * 0.6 && post_f > 0.0 {
        score += post_f * 0.25;
    }

    // Late-stream zero-tolerance — tighten harder near the end.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.45 * (progress - 0.72) * 4.0;
    }

    // Late-stream tightening.
    score *= 1.0 + 0.28 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let capacity_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Exact closure: overwhelming reward for perfectly filling a bin.
    if post_residual == 0 {
        score -= 950.0;
    } else if !is_new_bin && bin_residual == item_size {
        score -= 34.0 + 24.0 * progress;
    }

    // Two-step lookahead: chain packing.
    if next_item_size > 0 && !is_new_bin {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 3.0 {
                score -= 180.0;
            } else if slack <= 14.0 {
                score -= (54.0 - slack * 0.7).max(-18.0);
            } else {
                score -= (40.0 - slack * 0.35).max(-22.0);
            }
            if slack < 22.0 {
                score -= (22.0 - slack) * 1.7;
            }
            let rem = post_residual % next_item_size;
            if rem <= 3 {
                score -= 14.0 * (1.0 - progress);
            }
            let k = post_residual / next_item_size;
            if k >= 2 && post_residual - k * next_item_size <= 2 {
                score -= 20.0;
            }
            let depth = post_residual / next_item_size;
            if depth >= 3 {
                score -= (depth.min(6) as f64) * 5.0 * (0.5 + progress);
            }
            // Dead-space ratio refinement vs. what a fresh bin would leave.
            let next_waste = capacity_f - next_item_size as f64;
            if slack > next_waste * 0.6 {
                score += (slack - next_waste * 0.6) * 0.9 * (0.5 + progress);
            }
            if slack >= next_item_size as f64 {
                score -= 12.0 + 10.0 * progress;
            }
            // Near-multiple slack promises a longer self-sustaining chain.
            let mult = (slack as u32) / next_item_size;
            let mrem = (slack as u32) % next_item_size;
            if mult >= 1 && mrem <= 1 {
                score -= (mult.min(4) as f64) * 8.0 * (0.6 + progress);
            }
            // Exact 2x chain is golden.
            if post_residual == 2 * next_item_size {
                score -= 26.0 * (0.5 + progress);
            }
            // Pair-anticipation: post residual tiles with pairs of next item.
            if (slack as u32) >= 2 * next_item_size && (slack as u32) % (2 * next_item_size) == 0 {
                score -= 16.0 * progress;
            }
            // Tiny tail after next item = near-perfect chain.
            let tail = post_residual - next_item_size;
            if tail <= 2 {
                score -= 22.0 * (0.6 + progress);
            }
            // Spread guard: when many bins fit, only tightest chains earn.
            if fitting_bins_count > 2 && slack > 10.0 {
                score += (fitting_bins_count as f64 - 2.0).min(4.0) * 3.0;
            }
            // NEW: slack exactly half of next item anticipates a small filler item.
            if slack * 2.0 == next_item_size as f64 {
                score -= 15.0 * (0.5 + progress);
            }
            // NEW: combined-fit harmony — item + next <= residual with zero slack.
            if item_size as f64 + next_item_size as f64 == bin_residual as f64 {
                score -= 20.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * (0.48 + 0.24 * gap / capacity_f);
            if gap <= 4.0 && post_f > 0.0 {
                score -= 16.0 * (1.0 - progress);
            }
            if gap <= 2.0 {
                score -= 12.0;
            }
            let rel = gap / (next_item_size as f64).max(1.0);
            score += rel * 26.0 * (0.6 + 0.4 * progress);
            if gap <= capacity_f * 0.05 {
                score -= 6.0 * (1.0 - progress);
            }
            if gap > post_f * 0.6 {
                score += gap * 0.35 * progress;
            }
            // Recoverable dead space matching common small item band.
            if gap <= 12.0 && progress < 0.6 {
                score -= 7.0 * (1.0 - progress);
            }
            // NEW: gap exactly equal to item_size means the next item would
            // refill the bin to full — a perfect two-item closure opportunity.
            if gap == item_size as f64 {
                score -= 18.0 * (0.5 + progress);
            }
        }
    }

    // Reward tight fits: relative waste in the bin.
    if !is_new_bin && bin_residual > 0 {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fit_ratio * fit_ratio;
    }

    // Compare post_residual against mean residual.
    score -= (post_f - mean_residual) * 0.55;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 115.0;
    }

    // New-bin candidate logic.
    if is_new_bin {
        score += 50.0;
        score -= 30.0 * (1.0 - progress);
        let fresh_res = bin_capacity - item_size;
        let fresh_f = fresh_res as f64;
        if next_item_size > 0 && fresh_res >= next_item_size && fresh_res - next_item_size <= 8 {
            score -= 38.0;
        }
        if next_item_size > 0 && (next_item_size as i32 - fresh_res as i32).abs() < 6 {
            score += 14.0 * (1.0 - progress);
        }
        if item_size >= 60 && fresh_res <= 10 {
            score -= 40.0;
        }
        if item_size == bin_capacity {
            score -= 950.0;
        }
        if fitting_bins_count >= 1 {
            if post_residual <= 5 {
                score += 75.0;
            } else if post_f > capacity_f * 0.5 {
                score -= 30.0;
            } else if post_f <= capacity_f * 0.25 {
                score += 22.0 * (0.4 + 0.6 * progress);
            }
        }
        if open_bins_count > 2 && item_size as f64 > capacity_f * 0.8 {
            score += 26.0;
        }
        if fresh_f > 0.0 {
            score += (fresh_f / capacity_f) * 15.0 * progress;
        }
        if fresh_f > 18.0 && fresh_f < capacity_f * 0.45 {
            score += 9.0 * (1.0 - progress);
        }
        if progress < 0.2 && item_size as f64 > capacity_f * 0.65 {
            score -= 20.0;
        }
        if next_item_size > 0 {
            let ratio = fresh_f / (next_item_size.max(1) as f64);
            if ratio >= 1.0 && ratio < 2.0 {
                score -= 14.0;
            } else if fresh_f < 8.0 {
                score += 14.0;
            }
            if fresh_res == next_item_size {
                score -= 26.0 * (1.0 - progress);
            }
            let fmult = fresh_res / next_item_size;
            let frem = fresh_res % next_item_size;
            if fmult >= 2 && frem <= 2 {
                score -= (fmult.min(5) as f64) * 5.0;
            }
            let frac = ratio - ratio.floor();
            if ratio >= 1.0 && frac > 0.05 && frac < 0.4 {
                score += 10.0 * (0.5 + progress);
            }
        }
        // Never open fresh when item nearly fills an existing bin exactly.
        if fitting_bins_count >= 1 && bin_capacity - item_size <= 2 {
            score += 48.0;
        }
        // Late-stream fresh bins must be nearly self-closing.
        if progress > 0.7 && fresh_f > 0.0 && fresh_f < next_item_size.max(1) as f64 {
            score += 30.0 * progress;
        }
        if progress > 0.75 && fresh_f >= 12.0 {
            score += 18.0 * (progress - 0.75) * 4.0;
        }
        if progress > 0.8 && open_bins_count > 6 && fresh_f > 4.0 {
            score += 20.0 * progress;
        }
        // Tileable fresh residuals (multiples of 5/10) get a mid-stream discount.
        if fresh_res > 0 && progress < 0.7 && (fresh_res % 10 == 0 || fresh_res % 5 == 0) {
            score -= 8.0 * (1.0 - progress);
        }
        // Awkward 51..=60 fresh residual band is hard to tile.
        if fresh_f > 50.0 && fresh_f <= 60.0 {
            score += 10.0 * (0.5 + 0.5 * progress);
        }
        // NEW: refuse fresh bins when an existing bin can chain item+next perfectly.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            for_existing_chain_check(&mut score, item_size, next_item_size, post_residual);
        }
        score += 0.05 * mean_residual;
    } else {
        score -= 0.02 * mean_residual;
        score += 0.5 * open_bins_count as f64;
    }

    // Waste-proportional penalty scaled by progress.
    if post_f > 0.0 {
        score += (post_f / capacity_f) * (1.0 + progress) * (1.0 + 0.5 * progress);
        score += (post_f / capacity_f) * (1.0 + progress);
    }

    // Fragmentation guard: nearly-dead bins are cheap to use up.
    if !is_new_bin && (bin_residual as f64) < mean_residual * 0.3 {
        score -= 18.0;
    }

    // Half-capacity entropy guard.
    let half = capacity_f * 0.5;
    if post_f > half - 6.0 && post_f < half + 6.0 {
        score += 10.0 * (1.0 - progress);
    }
    if post_f > half && post_f < half + 12.0 {
        score += 6.0 * progress;
    }
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.0 * (0.4 + progress);
    }
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.4 * progress;
    }

    // Quarter/three-quarter dead zones are awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.0 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.0 * (1.0 - progress);
    }

    // Late-stream tightening.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.45 * (progress - 0.72) * 4.0;
    }
    score *= 1.0 + 0.28 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

#[inline(always)]
fn for_existing_chain_check(score: &mut f64, item_size: u32, next_item_size: u32, post_residual: u32) {
    // If an existing bin's post-residual after this item would exactly match
    // the next item, opening a fresh bin wastes that chain opportunity.
    if post_residual == next_item_size {
        *score += 60.0;
    } else if post_residual > next_item_size && post_residual - next_item_size <= 2 {
        *score += 35.0;
    }
    let _ = item_size;
}

