        if fitting_bins_count >= 1 {
            if post_residual as f64 <= 5 {
                score += 75.0;
            } else if post_f > capacity_f * 0.5 {
                score -= 30.0;
            } else if post_f <= capacity_f * 0.25 {
                score += 22.0 * (0.4 + 0.6 * progress);
