    // Waste-proportional penalty scaled by stream progress.
    if post_f > 0.0 {
        score += (post_f / capacity_f) * (1.0 + progress) * (1.0 + 0.55 * progress);
    }

    // Prefer filling bins tightly as the stream progresses.
    score += (post_f / capacity_f) * (1.0 + progress);

    // Slight penalty for spreading across many open bins.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.6;
