        let rem = post_residual % next_item_size;
        if rem <= 3 {
            score -= 15.0 * (1.0 - progress);
        }
        let k = post_residual / next_item_size;
        if k >= 2 && post_residual - k * next_item_size <= 2 {
            score -= 21.0;
        }
        // Multi-step chain depth.
        let depth = post_residual / next_item_size.max(1);
        if depth >= 3 {
            score -= (depth.min(6) as f64) * 5.5 * (0.5 + progress);
        }
        // Dead-space ratio refinement — penalize slack that exceeds the
        // fraction of capacity the next item would otherwise leave behind.
        let next_waste = capacity_f - next_item_size as f64;
        if slack > next_waste * 0.55 {
            score += (slack - next_waste * 0.55) * 1.05 * (0.5 + progress);
        }
        // Extendable chain reward.
        if slack >= next_item_size as f64 {
            score -= 12.0 + 10.0 * progress;
        }
        // NEW: near-multiple slack promises a longer chain.
        let mult = slack as u32 / next_item_size;
        let mrem = slack as u32 % next_item_size;
        if mult >= 1 && mrem <= 1 {
            score -= (mult.min(4) as f64) * 8.5 * (0.6 + progress);
        }
        // NEW: exact 2x-next residual is a golden two-step chain.
        if post_residual == 2 * next_item_size {
            score -= 27.0 * (0.5 + progress);
        }
        // Spread lookahead rewards only on the tightest candidates.
        if fitting_bins_count > 2 && slack > 10.0 {
            score += (fitting_bins_count as f64 - 2.0).min(4.0) * 3.2;
        }
        // NEW: tiny tail is near-perfect.
        if slack <= 2 {
            score -= 23.0 * (0.6 + progress);
        }
    }
    // Post-residual too small for the next item: dead space for lookahead.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * (0.5 + 0.24 * gap / capacity_f);
        if gap <= 4.0 && post_f > 0.0 {
            score -= 17.0 * (1.0 - progress);
        }
        if gap <= 2.0 {
            score -= 13.0;
        }
        // Gap relative to item size: large item with tiny gap is nearly closed.
        let rel = gap / (next_item_size as f64).max(1.0);
        score += rel * 27.0 * (0.6 + 0.4 * progress);
        // NEW: small recoverable gaps keep the chain alive early.
        if gap <= 12.0 && progress < 0.6 {
            score -= 7.5 * (1.0 - progress);
        }
        // NEW: gap dominating remaining space is pure waste.
        if gap > post_f * 0.6 {
            score += gap * 0.35 * progress;
        }
    }

    // Above-average residual left behind is good.
    score -= (post_f - mean_residual) * 0.58;

    // Exact closure reward.
    if post_residual == 0 {
        score -= 950.0;
    } else if bin_residual == item_size && bin_residual < bin_capacity {
        score -= 35.0 + 25.0 * progress;
    }

    // Last-chance bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 118.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 52.0;
        score -= 30.0 * (1.0 - progress);
        let fresh_res = bin_capacity - item_size;
        let fresh_f = fresh_res as f64;
        if next_item_size > 0 && fresh_res >= next_item_size && fresh_res - next_item_size <= 8 {
            score -= 39.0;
        }
        if next_item_size > 0 && (next_item_size as i32 - fresh_res as i32).abs() < 6 {
            score += 15.0 * (1.0 - progress);
