    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // Late-stream zero-tolerance.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions (1/2, 1/3, 1/4 of capacity)
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Reward tight fits: post_residual near zero is good (already baseline).
    // Penalize dead space that is too small to ever be useful:
    // post_residual in (0, 10) is a "dead zone" — nothing (min size 1..100 stream,
    // but small items are common) fits well; keep mild penalty.
    if post_residual > 0 && post_residual < quarter {
        score += (quarter - post_residual) as f64 * 0.5;
    }

    // Harmonic class matching: if item_size is in a harmonic class of the bin's
    // original fill, reward. Approximate via modulo of residual by item class.
    // Class of current item:
    let item_class = if item_size > half { 1 }
        else if item_size > third { 2 }
        else if item_size > quarter { 3 }
        else { 4 };

    // Reward bins whose residual is a near multiple of the item's class size band
    let class_band = bin_capacity / (item_class as u32 + 1);
    if class_band > 0 {
        let rem = bin_residual % class_band;
        if rem >= item_size && rem - item_size < quarter {
            score -= 4.0; // residue aligns: leaves a class-friendly remainder
        }
    }

    // Perfect fit bonus (modulo arithmetic on post_residual)
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual % 10 == 0 {
        score -= 3.0; // clean divisible remainder stays reusable
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            if leftover < quarter {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; slight penalty for wasting large residual
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Prefer filling fuller bins when many bins are open (consolidation pressure)
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 5.0;

    // New-bin candidate: penalize opening a new bin unless existing residuals
    // are badly fragmented (mean residual small) or item is huge.
    if bin_residual == bin_capacity {
        let huge_item = item_size > (bin_capacity * 2 / 3);
        let fragmented = mean_residual < (quarter as f64) && open_bins_count > 0;
        if huge_item && !fragmented {
            score += 12.0;
        } else if fragmented {
            score -= 5.0;
        } else {
            score += 6.0;
        }
    }

    // Late in stream: consolidate harder, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

