            // Near-exact multiple of next item with tiny remainder seeds a
            // long chain — stronger discount early.
            if fresh_res > next_item_size && frem <= 1 {
                score -= 12.0 * (1.0 - progress);
            }
        }
        // Never open a fresh bin when the item nearly fills an existing bin exactly.
        if fitting_bins_count >= 1 && bin_capacity - item_size <= 2 {
            score += 50.0;
        }
        // Late-stream fresh bins must be nearly self-closing.
        if progress > 0.7 && fresh_f > 0.0 && fresh_f < next_item_size.max(1) as f64 {
            score += 31.0 * progress;
        }
        if progress > 0.75 && fresh_f >= 12.0 {
            score += 19.0 * (progress - 0.75) * 4.0;
        }
        if progress > 0.8 && open_bins_count > 6 && fresh_f > 4.0 {
            score += 21.0 * progress;
        }
        // Tileable fresh residual (multiples of 5/10) — mild discount early.
        if fresh_res > 0 && progress < 0.7 && (fresh_res % 10 == 0 || fresh_res % 5 == 0) {
            score -= 8.0 * (1.0 - progress);
        }
        // Awkward 51..=60 residual band is hard to tile — penalize.
        if fresh_f > 50.0 && fresh_f <= 60.0 {
            score += 10.0 * (0.5 + 0.5 * progress);
        }
        // Refuse a fresh bin mid-stream if it strands over half the capacity
        // and the next item cannot use the remainder.
        if next_item_size > 0 && fresh_f > capacity_f * 0.5 && fresh_f < next_item_size as f64
            && progress > 0.3 {
            score += 24.0 * progress;
        }
    }

    // Waste-proportional penalty scaled by progress.
    if post_f > 0.0 {
        score += (post_f / capacity_f) * (1.0 + progress) * (1.0 + 0.55 * progress);
    }
    // Tightness term.
    score += (post_f / capacity_f) * (1.0 + progress);

    // Prefer consolidating into fewer open bins.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.6;
    }

    // Nearly-dead bins are cheap to use up.
    if (bin_residual as f64) < mean_residual * 0.3 && bin_residual < bin_capacity {
        score -= 19.0;
    }

    // Half-capacity dead zones seed fragmentation.
    let half = capacity_f * 0.5;
    if post_f > half - 6.0 && post_f < half + 6.0 {
        score += 10.5 * (1.0 - progress);
    }
    if post_f > half && post_f < half + 12.0 {
        score += 6.5 * progress;
    }
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets — squeeze hard.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.2 * (0.4 + progress);
    }
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.42 * progress;
    }

    // Quarter/three-quarter awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // Dead-space ratio term: near-dead vs. long-anchor residuals.
    if next_item_size > 0 && post_f > 0.0 {
        let dsr = post_f / (next_item_size as f64).max(1.0);
        if dsr < 0.25 && post_residual < next_item_size {
            score += 8.0 * (0.5 + progress);
        } else if dsr >= 2.0 && dsr <= 4.0 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Late-stream zero-tolerance — tighten harder near the end.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;

    let mut score = pr;

    // Reward tight fits: smooth quadratic decay of residual (smaller residual -> much lower score)
    score -= (1.0 - (pr / cap).powf(2.0)) * (40.0 + 30.0 * progress);

    // Reward large items filling big fraction of bin
    score -= fit_frac * fit_frac * 25.0;

    // Lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let slack = pr - ns;
            score -= (1.0 - slack / cap) * 35.0;
        } else {
            score += (ns - pr) / cap * 15.0;
        }
    }

    // Last-chance bin bonus: avoid opening new bin when only one fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Penalize many open bins mildly to encourage consolidation
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Nudge toward bins below mean residual (consolidate emptier space)
    score += (mean_residual - pr) * 0.15;

    // Smooth stream-progress coupling: early stream tolerates residual, late stream wants tight
    score += (1.0 - progress) * (pr / cap) * 10.0;

    score
}

