    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.05;

    // Tie-break: prefer bins with residual closest to item size (tight fit)
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

