        score += 5.5 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // Late-stream zero-tolerance.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // NEW: dead-space ratio term — penalize candidates whose post-residual
    // cannot pair with the next item even at half its size (true dead space).
    if next_item_size > 0 && post_f > 0.0 && post_f < (next_item_size as f64) * 0.5 {
        score += ((next_item_size as f64) * 0.5 - post_f) * 0.35 * (0.5 + progress);
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to accept any
    // future item (min item size 1, but practically tiny gaps) are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable sliver: worst possible outcome, quadratic penalty.
            score += 60.0 + (10 - post_residual) as f64 * 4.0;
        } else if post_residual <= 20 {
            // Marginal gap: only fits very small items; moderate penalty.
            score += 25.0;
        } else if post_residual <= 30 {
            score += 8.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 100.0;
    }

    // Reward tight fits (small post_residual relative to capacity) smoothly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and encourage consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin count.
        score += 20.0 + pressure;
    } else {
        score -= pressure.min(15.0);
    }

    // Lookahead (k=2): if the next item fits exactly in the post-residual,
    // strongly favor this bin; if next item would leave another sliver, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score -= 20.0; // chain fill that closes the bin nicely
            } else {
                score -= 8.0;
            }
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 5.0; // next item won't fit here; sliver risk
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average)
    // to keep a spread of usable gaps across bins.
    score += 0.5 * ((post_residual as f64) - mean_residual);

    score
}

