    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets — squeeze them hard mid-stream.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.2 * (0.4 + progress);
    }

    // 7..15 band is the next-worst seed zone; mildly discourage late.
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.42 * progress;
    }

    // Quarter/three-quarter dead zones are awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // Post residual that exactly equals next_item_size plus a tiny
    // remainder still leaves a near-perfect two-step chain — reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let tail = post_residual - next_item_size;
        if tail > 0 && tail <= 2 {
            score -= 23.0 * (0.6 + progress);
        }
    }

    // Dead-space ratio term — penalize near-dead residuals, reward anchors.
    if next_item_size > 0 && post_f > 0.0 {
        let dsr = post_f / (next_item_size as f64).max(1.0);
        if dsr < 0.25 && post_residual < next_item_size {
            score += 8.0 * (0.5 + progress);
        } else if dsr >= 2.0 && dsr <= 4.0 {
            score -= 6.5 * (1.0 - progress);
        }
    }

    // Late-stream zero-tolerance — tighten harder near the end.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual, non-linearly coupled with stream progress.
    // Early on, prefer tight fills (minimize post_residual strongly);
    // later, dead space matters even more, so penalize quadratically.
    let mut score = pr * (1.0 + 1.5 * pr_norm * pr_norm);
    score += 4.0 * progress * pr_norm * pr_norm * cap;

    // Reward using a bin whose residual would otherwise be stranded:
    // last-chance bins get a strong bonus, smoothly scaled by fit tightness.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * (1.0 - pr_norm);
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // reward strongly; if post_residual is just barely too small for the
    // next item, penalize (wasted near-fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            score -= 8.0 * (1.0 - diff / cap);
        } else {
            score += 5.0 * (-diff / cap);
        }
    }

    // Smooth penalty when bin residual deviates from the mean residual
    // (favor bins with unusually low residual, i.e. nearly full ones).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild pressure against opening many bins early.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline, penalized unless item is
    // large relative to capacity (better to start fresh for big items).
    if bin_residual == bin_capacity {
        score = cap * 0.6 - item_size as f64 + 5.0 * progress;
    }

    score
}

