    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals that are "harmonically compatible" with common item sizes are less wasteful.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: small post_residual (< smallest item, i.e. <10) is perfect fill.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual < 10 {
        score -= 50.0; // unusable sliver = effectively full bin, reward
    } else {
        // Penalize residual classes that are hard to fill: use integer division thresholds.
        // post_residual in [10, 19] is awkward (only tiny items fit) -> strong penalty.
        if post_residual < 20 {
            score += 30.0;
        }
        // Harmonic class via modulo: residuals divisible by common item sizes are reusable.
        let r = post_residual;
        if r % 10 == 0 {
            score -= 8.0; // decade-aligned residual: many items fit exactly
        } else if r % 5 == 0 {
            score -= 3.0;
        }
        // Fractional capacity classes: residual near half or quarter capacity is flexible.
        let half = cap / 2.0;
        let quarter = cap / 4.0;
        let d_half = (post - half).abs();
        let d_quarter = (post - quarter).abs();
        score -= 6.0 * (1.0 - d_half / half).max(0.0);
        score -= 3.0 * (1.0 - d_quarter / quarter).max(0.0);
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain fit: reward, scaled by how exactly it fills
            let fill_frac = next_item_size as f64 / post.max(1.0);
            score -= 20.0 * fill_frac;
