        } else {
            // next item won't fit here: mild penalty for breaking chains
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Prefer existing bins when a reasonable fit exists; open new bin only for bad fits.
        // Base cost of opening a new bin:
        score += 40.0;
        // But if current item is large and leaves a harmonic residual, new bin is attractive.
        if item_size >= bin_capacity / 2 && post_residual % 10 == 0 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If many bins already open, discourage another.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild global pressure: keep scores comparable to mean residual state.
    score += 0.05 * (mean_residual - post);

    score
}

