        } else {
            // Next item cannot use the leftover: penalize dead space,
            // scaled by how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    } else {
        // Last item: leftover is pure waste; prefer minimal residual.
        score += 50.0;
    }

    // Penalize large post residuals relative to the mean residual of open bins
    // (creating more slack than average is wasteful unless lookahead helps).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual) * (1.0 - 0.5 * progress);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
