    // New-bin candidate: give it a moderate baseline so it is chosen only when
    // no open bin offers a good fit or lookahead chain.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Early in the stream, opening fresh bins is cheaper (more future items
        // to co-fill); late in the stream, prefer consolidating.
        score += 60.0 * (1.0 - progress);
        // If many bins are open, discourage adding more.
        score += 2.0 * open_bins_count as f64;
    }

    // Small tie-breaker favoring tighter fits overall.
    score += 0.1 * post_residual as f64;

    score
}

