        if progress > 0.8 && open_bins_count > 6 && fresh_f > 4.0 {
            score += 21.0 * progress;
        }
        // NEW: fresh bin with mid-range residual is only worth it if it chains.
        if fresh_f >= 20.0 && next_item_size > 0 && fresh_f < next_item_size as f64 {
