    if (bin_residual as f64) < mean_residual * 0.3 && bin_residual < bin_capacity {
        score -= 19.0;
    }

    // Half-capacity dead zones seed fragmentation.
    let half = capacity_f * 0.5;
    if post_f > half - 6.0 && post_f < half + 6.0 {
        score += 10.5 * (1.0 - progress);
    }
    if post_f > half && post_f < half + 12.0 {
        score += 6.5 * progress;
    }
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.2 * (0.4 + progress);
    }
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.42 * progress;
    }

    // Quarter/three-quarter awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // NEW: mid-band residual (just above half) is high-risk dead space.
    if post_f > half + 12.0 && post_f <= half + 22.0 && progress > 0.35 {
        score += (post_f - half - 12.0) * 0.55 * progress;
    }

    // Late-stream zero-tolerance.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post residual (tight packing).
    let mut score = pr;

    // Smooth tight-fit reward: strongest when post_residual is small relative to capacity.
    let tightness = 1.0 - (pr / cap);
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Non-linear coupling of item size with progress: reward consuming large items
    // into existing bins more strongly later in the stream.
    score -= 0.05 * (it / cap) * (it / cap) * (1.0 + 2.0 * progress) * (bin_residual as f64 - pr);

    // Penalize leaving residuals that are unlikely to fit future items.
    // Dead space penalty grows quadratically with post residual but is smoothed
    // by the mean residual across open bins.
    let dead = (pr - mean_residual.abs().min(pr)) / cap;
    score += 6.0 * dead * dead * (1.0 - 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - pr / cap);
    }

    // New-bin candidate handling: empty bin gets a smooth penalty that shrinks
    // with progress and with how poor the alternatives are (high mean residual waste).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin wastes nothing now, but forfeits tight-fit rewards:
        // penalize so it's chosen only when open bins would leave big residuals.
        let waste_if_used = (mean_residual - it).max(0.0) / cap;
        score += 10.0 * (1.0 - progress) * (1.0 - waste_if_used.min(1.0));
        score += 3.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    } else {
        // Slight preference for bins whose residual after placement still matches
        // the next item (lookahead smoothing, quadratic coupling).
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let match_term = (pr - nxt).abs() / cap;
            score += 4.0 * match_term * match_term * (0.5 + 0.5 * progress);
