    // Coupling with mean residual: prefer bins whose post-residual is near the mean (balance)
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate: mild penalty so we prefer reusing bins unless they fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

