    }

    // Mean-residual coupling: prefer bins whose residual is below mean (fill the fullest bins).
    score += ((bin_residual as f64) - mean_residual) * 0.2;

    // Stream progression: later in stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    // Slight preference for bins with residual close to item size (tight fit harmonic).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    score
}

