        }
        if progress > 0.75 && fresh_f >= 12.0 {
            score += 19.0 * (progress - 0.75) * 4.0;
        }
        if progress > 0.8 && open_bins_count > 6 && fresh_f > 4.0 {
            score += 21.0 * progress;
        }
        // NEW: mid-stream fresh bins must beat the best existing candidate by a
        // real margin — penalize opening when existing post-residuals are decent.
        if fitting_bins_count >= 1 && post_f > 0.0 && progress > 0.3 && progress < 0.75 {
            score += (post_f / capacity_f) * 26.0 * (0.5 + progress);
