pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = post / cap;

    // Base: penalize wasted residual, quadratically amplified.
    let mut score = post * (1.0 + fit_norm * fit_norm);

    // Smooth polynomial coupling of residual with stream progress:
    // late in the stream, waste matters more.
    let late = progress * progress * (3.0 - 2.0 * progress);
    score += post * post / cap * late * 2.0;

    // Reward tight fits (small post_residual) smoothly via inverse term.
    score -= (cap / (post + 1.0)).min(10.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * late;
    }

    // Mild penalty when many bins are open (discourage bin proliferation).
    score += (open_bins_count as f64).sqrt() * (post / cap) * 2.0;

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post) * 0.3;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 5.0 + 10.0 * (1.0 - (post - nxt) / cap);
        } else {
            // If next item cannot fit here, slightly penalize near-full residuals
            // that leave awkward space; smooth via cubic term.
            let gap = (post / cap).powi(3);
            score += gap * 15.0;
        }
    }

    // New-bin candidate: neutral-ish baseline; opening a new bin is only
    // attractive when residuals across open bins are already small.
    if bin_residual == bin_capacity {
        score = cap * 0.5 + mean_residual * 0.5;
    }

    score
}

