        && bin_residual - (item_size + next_item_size) <= 2
    {
        score -= 18.0 * (0.5 + progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 52.0;
        score -= 30.0 * (1.0 - progress);
        let fresh_res = bin_capacity - item_size;
        let fresh_f = fresh_res as f64;
        if next_item_size > 0 && fresh_res >= next_item_size && fresh_res - next_item_size <= 8 {
            score -= 39.0;
        }
        if next_item_size > 0 && (next_item_size as i32 - fresh_res as i32).abs() < 6 {
            score += 15.0 * (1.0 - progress);
        }
        if item_size >= 60 && fresh_res <= 10 {
            score -= 42.0;
        }
        if item_size == bin_capacity {
            score -= 950.0;
        }
        if fitting_bins_count >= 1 && post_residual > 35 {
            score -= 33.0;
        }
        if open_bins_count > 2 && item_size as f64 > capacity_f * 0.8 {
            score += 27.0;
        }
        if fresh_f > 0.0 {
            score += (fresh_f / capacity_f) * 15.0 * progress;
        }
        if fresh_f > 18.0 && fresh_f < capacity_f * 0.45 {
            score += 9.5 * (1.0 - progress);
        }
        // Refuse a fresh bin when some existing bin already yields a tight fit.
        if fitting_bins_count >= 1 {
            if post_residual as f64 <= 5.0 {
                score += 78.0;
            } else if post_f > capacity_f * 0.5 {
                score -= 31.0;
            } else if post_f <= capacity_f * 0.25 {
                score += 23.0 * (0.4 + 0.6 * progress);
            }
        }
        if progress < 0.2 && item_size as f64 > capacity_f * 0.65 {
            score -= 21.0;
        }
        // Fresh-bin residual quality — reusable residuals are cheap to open.
        if next_item_size > 0 {
            let ratio = fresh_f / (next_item_size.max(1) as f64);
            if ratio >= 1.0 && ratio < 2.0 {
                score -= 15.0;
            } else if fresh_f < 8.0 {
                score += 15.0;
            }
            if fresh_res == next_item_size {
                score -= 27.0 * (1.0 - progress);
            }
            let fmult = fresh_res / next_item_size;
            let frem = fresh_res % next_item_size;
            if fmult >= 2 && frem <= 2 {
                score -= (fmult.min(5) as f64) * 5.5;
            }
            // Awkward fractional multiples seed fragmentation.
            let frac = ratio - ratio.floor();
            if ratio >= 1.0 && frac > 0.05 && frac < 0.4 {
                score += 11.0 * (0.5 + progress);
            }
            // Fresh residual tileable by next item with tiny remainder.
            if fresh_res > next_item_size && fresh_res % next_item_size <= 1 {
                score -= 12.0 * (1.0 - progress);
            }
            // Large fresh residual that cannot fit next item late-stream is dead space.
            if fresh_f > capacity_f * 0.5 && fresh_f < next_item_size as f64 && progress > 0.3 {
                score += 24.0 * progress;
            }
        }
        // Never open a fresh bin when the item nearly fills an existing bin exactly.
        if fitting_bins_count >= 1 && bin_capacity - item_size <= 2 {
            score += 50.0;
        }
        // Late-stream fresh bins must be nearly self-closing.
        if progress > 0.7 && fresh_f > 0.0 && fresh_f < next_item_size.max(1) as f64 {
            score += 31.0 * progress;
        }
        if progress > 0.75 && fresh_f >= 12.0 {
            score += 19.0 * (progress - 0.75) * 4.0;
        }
        if progress > 0.8 && open_bins_count > 6 && fresh_f > 4.0 {
            score += 21.0 * progress;
        }
        // Fresh residual tileable by small common sizes is a recoverable seed.
        if fresh_res > 0 && fresh_res <= 48 && progress < 0.55
            && (fresh_res % 4 == 0 || fresh_res % 6 == 0 || fresh_res % 8 == 0 || fresh_res % 12 == 0) {
            score -= 7.0 * (1.0 - progress);
        }
        // Refuse a fresh bin when an existing bin gives a perfect or near-perfect
        // two-step chain (dead-space guard).
        if next_item_size > 0 && fitting_bins_count >= 1
            && (post_residual == next_item_size
                || (post_residual > next_item_size && post_residual - next_item_size <= 3)) {
            score += 60.0;
        }
        // Refuse a fresh bin when an existing bin closes exactly with item + next item.
        if next_item_size > 0 && fitting_bins_count >= 1
            && bin_capacity == item_size + next_item_size {
            score += 55.0;
        }
        // NEW: refuse fresh bin when an existing bin leaves room for item + next.
        if next_item_size > 0 && fitting_bins_count >= 1
            && bin_residual >= item_size + next_item_size
            && bin_residual - (item_size + next_item_size) <= 4 {
            score += 34.0;
        }
    }

    // Waste-proportional penalty scaled by stream progress.
    if post_f > 0.0 {
        score += (post_f / capacity_f) * (1.0 + progress) * (1.0 + 0.55 * progress);
    }
    // Prefer filling bins tightly as the stream progresses.
    score += (post_f / capacity_f) * (1.0 + progress);

    // Slight penalty for spreading across many open bins.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.6;
    }

    // Fragmentation guard: nearly-dead bins are cheap to use up.
    if (bin_residual as f64) < mean_residual * 0.3 && bin_residual < bin_capacity {
        score -= 19.0;
    }

    // Dead-space entropy guard: residuals near half capacity seed fragmentation.
    let half = capacity_f * 0.5;
    if post_f > half - 6.0 && post_f < half + 6.0 {
        score += 10.5 * (1.0 - progress);
    }
    if post_f > half && post_f < half + 12.0 {
        score += 6.5 * progress;
    }
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets — squeeze them hard mid-stream.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.2 * (0.4 + progress);
    }
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.42 * progress;
    }

    // Quarter/three-quarter dead zones are awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // Tiny tail after next item is near-perfect.
    if next_item_size > 0 && post_residual > next_item_size {
        let tail = post_residual - next_item_size;
        if tail > 0 && tail <= 2 {
            score -= 22.0 * (0.6 + progress);
        }
    }

    // Dead-space ratio term.
    if next_item_size > 0 && post_f > 0.0 {
        let dsr = post_f / (next_item_size as f64).max(1.0);
        if dsr < 0.25 && post_residual < next_item_size {
            score += 8.0 * (0.5 + progress);
        } else if dsr >= 2.0 && dsr <= 4.0 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // NEW: two-step compaction — bin absorbs item, next item, and the one after
    // is implied by a residual equal to a small multiple of next_item_size.
    if next_item_size > 0 && post_residual > 0 && post_residual % (2 * next_item_size.max(1)) == 0 && post_residual != bin_capacity {
        score -= 14.0 * (0.5 + progress);
    }

    // Late-stream zero-tolerance — tighten harder near the end.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "large" classes (>= 50) remain useful for future mid-size items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Integer-division thresholds on post_residual create harmonic bands.
    let band = post_residual / 10; // 0..=10 harmonic class
    match band {
        0 => score -= 8.0,        // near-perfect fill (0..9 leftover)
        1 => score -= 4.0,        // excellent fill
        2 => score -= 2.0,        // good fill
        3 | 4 => score += 1.5,    // awkward mid dead-space
        5 | 6 => score += 0.0,    // neutral: half-full leftovers are flexible
        7 | 8 => score -= 1.0,    // large residual, still very usable
        _ => score -= 2.5,        // nearly empty bin: keep it for big items
    }

    // Modulo arithmetic on post_residual: multiples of 10 pair cleanly with
    // the 10..80 item size grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }
    // Odd leftovers under 10 are dead space (min item size is 10 in classic
    // streams, but be safe for sizes 1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let next_band = (post_residual - next_item_size) / 10;
            if next_band == 0 {
                score -= 5.0; // next item leaves near-perfect fill too
            }
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    if progress > 0.7 {
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Slight preference for bins below the mean residual (tighter packs).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when residual spread is large or
    // item is huge relative to typical open-bin residuals.
    if bin_residual == bin_capacity {
        let big_item_bonus = if item_size > 60 { 6.0 } else { 0.0 };
        score += 4.0 - big_item_bonus + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0; // stacking two big items in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
