    if next_item_size > 0 && post_f > 0.0 && post_f < next_item_size as f64 && post_f <= 10.0 && progress < 0.45 {
        score -= 6.0 * (1.0 - progress);
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "unusable" as a gap smaller than the smallest plausible item (10)
    // or a gap that no item in the reasonable range can efficiently use.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += 60.0 * (10.0 - gap); // tiny slivers are pure waste
    } else if gap > 0.0 && gap < 25.0 {
        // partially usable gap: moderate penalty, worse the smaller it is
        score += 1.5 * (25.0 - gap);
    }

    // Reward tight fits (post_residual near zero but not a dead sliver)
    if gap == 0.0 {
        score -= 40.0; // perfect fill
