    // using it over opening a new bin (unless post_residual is terrible).
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: a fresh empty bin should only win when the
    // item is huge relative to capacity or no open bin fits well. Penalize
