    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty for dead space.
    score += (post_residual as f64) * (post_residual as f64) / cap;

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small residuals are hard to reuse; penalize leaving tiny crumbs.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            score -= 45.0;
