            score -= 15.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 8.0 * (1.0 - (post_residual as f64) / nxt.max(1.0));
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that are more filled (small residual).
        score -= 10.0 * (1.0 - (bin_residual as f64) / cap);
    }

    // Global state coupling: if mean residual is high, prefer reusing open bins
    // over creating new ones; if low, opening a new bin is less costly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_gap = mean_residual - (bin_residual as f64);
    score += 0.05 * mean_gap * (1.0 + progress);

    // New-bin candidate handling: penalize opening a new bin, but relax the
