        new_bin_penalty -= 30.0 * (item_size as f64 / cap);
        // Late in the stream, consolidation matters more.
        new_bin_penalty += 20.0 * progress;
        // If many bins already fit the item, discourage a new bin more.
        if fitting_bins_count > 0 {
            new_bin_penalty += 15.0 * (fitting_bins_count.min(5) as f64);
        }
        score += new_bin_penalty;
    }

    // Mild preference for bins whose residual is close to a typical item size
    // (multiples of 10), improving future usability.
    let r = post_residual as f64;
    let nearest10 = (r / 10.0).round() * 10.0;
    score += 0.3 * (r - nearest10).abs();

    score
}

