    if post_f > half && post_f < half + 12.0 {
        score += 6.5 * progress;
    }
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.2 * (0.4 + progress);
    }
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.42 * progress;
    }

    // Quarter/three-quarter awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // Late-stream zero-tolerance.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // NEW: residual entropy guard — residuals far from mean fragment the stream.
    if post_f > 0.0 && next_item_size > 0 {
        let dev = (post_f - mean_residual).abs();
        if dev > capacity_f * 0.35 {
            score += dev * 0.12 * progress;
        }
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward placements that leave "harmonic" leftovers (nice fractions pack well later).
    let harmonics: [f64; 6] = [0.0, 0.1, 0.2, 0.25, 0.5, 0.75];
    let mut best_h = f64::INFINITY;
    for h in harmonics.iter() {
        let d = (frac - h).abs();
        if d < best_h { best_h = d; }
    }
    score -= 12.0 * (1.0 - best_h * 4.0).max(0.0);

    // Penalize dead space: leftover too small to fit any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Modulo-class coupling between item and residual: complementary sizes (sum near capacity).
    let s = (item_size + post_residual) as i64;
    let m = s % 100;
    if m == 0 { score -= 8.0; }
    else if m <= 10 { score -= 4.0; }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 15.0;
    }
    // Penalize leaving residual that next item cannot use at all.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate: neutral-ish score that scales with stream progress and current bin count.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more when many bins already fit the item
        // and less when the stream is early (room to combine future items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 35.0 + 20.0 * (1.0 - progress) + 3.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin may be useful
        }
    }

    // Slight preference for filling fuller bins (tighter residual).
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

