        score -= 19.0;
    }

    // Half-capacity dead zones seed fragmentation.
    let half = capacity_f * 0.5;
    if post_f > half - 6.0 && post_f < half + 6.0 {
        score += 10.5 * (1.0 - progress);
    }
    if post_f > half && post_f < half + 12.0 {
        score += 6.5 * progress;
    }
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.2 * (0.4 + progress);
    }
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.42 * progress;
    }

    // Quarter/three-quarter awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // Late-stream zero-tolerance.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // MUTATION: prefer bins whose residual is a near-multiple of the next item even without exact fit.
    if next_item_size > 1 && post_residual >= next_item_size {
        let nrem = post_residual % next_item_size;
        if nrem == 0 {
            score -= 6.0 * (0.5 + progress);
        }
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: heavily reward bins whose post_residual is small.
    let perfect = 8.0 * (1.0 - (post_residual as f64) / bin_capacity as f64).powi(6);
    score -= perfect;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportional to how tightly the next item fits the leftover space.
            let tightness = 1.0 - ((post_residual - next_item_size) as f64) / bin_capacity as f64;
            score -= 6.0 * tightness;
            // Exact chain fill (post_residual == next_item_size) is ideal.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Penalize leaving dead space the next item cannot use.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(40.0);
        }
    } else {
        // Last item: pure tight-fit preference.
        score -= 5.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins with residual below mean are "precious";
    // filling them is good, so reward that; bins far above mean are loose.
    let rel = (bin_residual as f64 - mean_residual).max(-50.0).min(50.0);
    score -= 0.05 * rel;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual <= 10 {
            score -= 6.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin, more so as stream progresses
    // and more open bins exist (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // Exception: if the item is huge relative to typical residual space,
        // opening fresh is less bad.
        if (item_size as f64) > mean_residual {
            score -= 8.0;
        }
    }

    // Mild preference for keeping many bins open when residuals are fragmented:
    // discourage spreading across bins when mean residual is already low.
    if mean_residual < 15.0 && bin_residual != bin_capacity {
        score += 2.0;
    }

    score
}

