    // late in the stream, just close out bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate handling: opening a fresh bin is only attractive for large items
