    if post_f > half && post_f < half + 12.0 {
        score += 6.5 * progress;
    }
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.2 * (0.4 + progress);
    }
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.42 * progress;
    }

    // Quarter/three-quarter awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // Late-stream zero-tolerance.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // NEW: mid-stream residual variance control — avoid leaving residuals far
    // from the current mean, which correlates with stranded dead space.
    if post_f > 0.0 {
        let dev = (post_f - mean_residual).abs();
        if dev > capacity_f * 0.3 && progress > 0.25 {
            score += (dev - capacity_f * 0.3) * 0.22 * progress;
        }
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual divisible by small sizes is reusable
    let pr = post_residual;
    let mut reusability = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { reusability += 6.0; }
        if pr % 25 == 0 { reusability += 4.0; }
        if pr % 20 == 0 { reusability += 3.0; }
        if pr % 50 == 0 { reusability += 5.0; }
        // small residuals are dead space
        if pr < 10 { reusability -= 8.0; }
        else if pr < 20 { reusability -= 4.0; }
    } else {
        reusability += 10.0;
    }
    score -= reusability;

    // Lookahead coupling: does post_residual fit the next item exactly?
    if next_item_size > 0 && next_item_size <= pr {
        if pr == next_item_size {
            score -= 300.0;
        } else if pr % next_item_size == 0 {
            score -= 40.0;
        } else {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportional to waste
        score += (next_item_size as f64) * 0.3;
    }

    // Capacity fraction thresholds on residual
    let frac = bin_residual as f64 / bin_capacity as f64;
    if frac > 0.75 {
        score -= 20.0; // prefer filling large-residual bins
    } else if frac < 0.3 {
        score += 10.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 250.0
            + open_bins_count as f64 * 5.0
            + (post_residual as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 400.0;
