            score -= 6.0 * (1.0 - progress);
        }
    }

    // Late-stream zero-tolerance.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never host even the
    // smallest item (size 1) are pure waste; small-but-nonzero gaps below the
    // typical item floor are especially bad.
    if post_residual == 0 {
        score -= 40.0; // perfect fill, ideal
    } else if post_residual < 10 {
        score += 60.0; // unusable sliver gap -> strong penalty
    } else if post_residual < 20 {
        score += 25.0; // likely dead space for most distributions
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spawning new ones.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only attractive when the current item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64 > 0.6;
        let poor_fit = post_residual < 10;
        if large_item || poor_fit || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 35.0; // keep existing bins tight; don't open new ones casually
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward
    // this placement strongly (creates a perfect follow-up).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
