            score += (4.0 - post_f) * 2.2 * progress;
        }
    }

    // Above-average residual left behind is good.
    score -= (post_f - mean_residual) * 0.58;

    // Exact closure reward.
    if post_residual == 0 {
        score -= 950.0;
    } else if bin_residual == item_size && bin_residual < bin_capacity {
        score -= 35.0 + 25.0 * progress;
    }

    // Last-chance bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 118.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 52.0;
        score -= 30.0 * (1.0 - progress);
        let fresh_res = bin_capacity - item_size;
        let fresh_f = fresh_res as f64;
        if next_item_size > 0 && fresh_res >= next_item_size && fresh_res - next_item_size <= 8 {
            score -= 39.0;
        }
        if next_item_size > 0 && (next_item_size as i32 - fresh_res as i32).abs() < 6 {
            score += 15.0 * (1.0 - progress);
        }
        if item_size >= 60 && fresh_res <= 10 {
            score -= 42.0;
        }
        if item_size == bin_capacity {
            score -= 950.0;
        }
        if fitting_bins_count >= 1 && post_residual > 35 {
            score -= 33.0;
        }
        if open_bins_count > 2 && item_size as f64 > capacity_f * 0.8 {
            score += 27.0;
        }
        if fresh_f > 0.0 {
            score += (fresh_f / capacity_f) * 15.0 * progress;
        }
        if fresh_f > 18.0 && fresh_f < capacity_f * 0.45 {
            score += 9.5 * (1.0 - progress);
        }
        // Refuse a fresh bin when an existing bin yields a tight fit.
        if fitting_bins_count >= 1 {
            if post_residual as f64 <= 5.0 {
                score += 78.0;
            } else if post_f > capacity_f * 0.5 {
                score -= 31.0;
            } else if post_f <= capacity_f * 0.25 {
                score += 23.0 * (0.4 + 0.6 * progress);
