    }

    // Nearly-dead bins are cheap to use up.
    if (bin_residual as f64) < mean_residual * 0.3 && bin_residual < bin_capacity {
        score -= 19.0;
    }

    // Half-capacity dead zones seed fragmentation.
    let half = capacity_f * 0.5;
    if post_f > half - 6.0 && post_f < half + 6.0 {
        score += 10.5 * (1.0 - progress);
    }
    if post_f > half && post_f < half + 12.0 {
        score += 6.5 * progress;
    }
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.2 * (0.4 + progress);
    }
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.42 * progress;
    }

    // Quarter/three-quarter awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // Late-stream zero-tolerance.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // Dead-space ratio term — penalize candidates whose post-residual
    // cannot pair with the next item even at half its size (true dead space).
    if next_item_size > 0 && post_f > 0.0 && post_f < (next_item_size as f64) * 0.5 {
        score += ((next_item_size as f64) * 0.5 - post_f) * 0.35 * (0.5 + progress);
    }

    // Lookahead-aware dead-space — if post residual is below next item but
    // within the smallest plausible item band (1..=10), it may still be usable;
    // soften the trap penalty accordingly early in the stream.
    if next_item_size > 0 && post_f > 0.0 && post_f < next_item_size as f64 && post_f <= 10.0 && progress < 0.45 {
        score -= 6.0 * (1.0 - progress);
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with a smooth non-linear polynomial coupling
    // to stream progress. Late in the stream, tight fits are weighted more heavily.
    let mut score = pr * (1.0 + 2.0 * progress * progress) + cap * 6.0 * progress * norm_pr * norm_pr;

    // Dead-space penalty: residuals too small to fit typical future items.
    let dead_zone = (norm_pr - 0.12).max(0.0) * (0.12 - norm_pr).max(0.0);
    score += 40.0 * dead_zone;

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: reward if next item fits into post-residual (smooth coupling).
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as f64;
        score -= 8.0 * fits_next * (1.0 + progress);
        // Mild penalty for post-residuals that just barely miss the next item.
        let miss = ((next_item_size as f64 - pr) / cap).max(0.0);
        score += 15.0 * miss * miss * cap;
    }

    // Crowd penalty: with many open bins, discourage spreading into loose fits.
    let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / cap);
    score += 2.0 * crowd * norm_pr * (1.0 - progress * 0.5);

    // New-bin candidate: make it moderately attractive early, less so late.
    if bin_residual == bin_capacity {
        score = cap * (1.2 - 0.7 * progress) + 10.0 * progress;
    }

    score
}

