pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual via integer division thresholds.
    // Class dead-space granularity: waste <= 10 is near-perfect; waste in
    // (10,20] acceptable; > 20 is dead space that later items rarely fill.
    let waste = post_residual as f64;
    if post_residual <= 10 {
        score -= 120.0; // class 0: tiny residual, effectively closed
    } else if post_residual <= 20 {
        score -= 60.0; // class 1: small, still fillable by min-size items
    } else if post_residual <= 40 {
        score -= 15.0; // class 2: medium
    } else {
        score += 10.0; // class 3: large residual, keep flexible
    }

    // Modulo arithmetic on residual: residuals that are multiples of the
    // smallest item size (harmonic with the item universe) are easier to fill.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead harmony: does the next item fit exactly or partially?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 2.0; // good follow-up
            score -= 25.0;
        } else {
            // Next item cannot use this residual: dead space risk grows
            // especially in the small-waste classes where nothing fits anyway.
            score += waste * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 90.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate detection: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when many bins compete poorly
        // (i.e. this is NOT a last chance) and residual left would be small.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 200.0; // default: prefer existing bins
        if fitting_bins_count == 0 {
            score -= 300.0; // forced: no open bin fits
        }
        // Late in the stream, avoid proliferating bins with big residuals.
        if post_residual > 20 && progress > 0.5 {
            score += 40.0 * (post_residual as f64 / bin_capacity as f64);
        }
        // Early stream: opening fresh bins with clean multiples is okay.
        if post_residual % 10 == 0 && progress < 0.3 {
            score -= 60.0;
        }
    }

    // Mild pressure toward tighter overall packing state.
    score += (mean_residual - waste).abs() * 0.1;

    score
}

