        let rel = gap / (next_item_size as f64).max(1.0);
        score += rel * 27.0 * (0.6 + 0.4 * progress);
        if gap <= 12.0 && progress < 0.6 {
            score -= 7.5 * (1.0 - progress);
        }
        if gap > post_f * 0.6 {
            score += gap * 0.35 * progress;
        }
        // Small gap with a "friendly" post residual (multiple of 5) is recoverable.
        if gap >= 1.0 && gap <= 6.0 && post_residual % 5 <= 2 {
            score -= 5.0 * (1.0 - progress);
        }
        // Large relative gap mid-stream is a fragmentation seed.
        let gap_ratio = gap / (next_item_size as f64).max(1.0);
        if gap_ratio > 0.6 && gap > 14.0 {
            score += gap * 0.22 * (0.5 + progress);
        } else if gap_ratio <= 0.15 && post_f >= 3.0 {
            score -= 5.0 * (1.0 - progress);
        }
