    if next_item_size > 0 && post_residual > next_item_size {
        let tail = post_residual - next_item_size;
        if tail > 0 && tail <= 2 {
            score -= 22.0 * (0.6 + progress);
        }
    }

    // Dead-space ratio term.
    if next_item_size > 0 && post_f > 0.0 {
        let dsr = post_f / (next_item_size as f64).max(1.0);
        if dsr < 0.25 && post_residual < next_item_size {
            score += 8.0 * (0.5 + progress);
        } else if dsr >= 2.0 && dsr <= 4.0 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Late-stream zero-tolerance — tighten harder near the end.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    // Items are >= 1, but treat gaps < 10 as near-wasted (classic small-item floor).
    if post_residual < 10 {
        score += 120.0;
    } else if post_residual < 20 {
        score += 40.0;
    } else if post_residual < 30 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here: penalize leaving a gap the next item can't use.
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should win only when no open bin offers a decent fit; make empty bins
    // moderately attractive by default but beatable by any reasonable fit.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            // handled above for the fitting bin; here just keep new bin unattractive
            score += 30.0;
        }
    }

    // Slight preference for bins whose residual is close to the mean (keep residuals uniform).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

