        score += 10.5 * (1.0 - progress);
    }
    if post_f > half && post_f < half + 12.0 {
        score += 6.5 * progress;
    }
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.2 * (0.4 + progress);
    }
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.42 * progress;
    }

    // Quarter/three-quarter awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // Late-stream zero-tolerance.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact or near-exact match
    // between post_residual and the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: huge reward (subtract heavily).
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward scaled by closeness of fit.
            score -= 20.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit in residual: penalize leaving awkward space.
            score += 10.0 * (diff / bin_capacity as f64);
        }
    }

    // Penalize large dead space relative to mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual < bin_capacity as u32 {
        score -= 15.0;
    }

    // Mild bonus for tight fits (small post residual) — classic best-fit behavior.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.1;

    // New-bin candidate: only attractive when item barely fits anywhere else
    // (i.e., this empty-bin call has full residual and item is large).
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; slight penalty so we prefer existing bins
        // unless lookahead rewards above make an open bin clearly better.
        score += 5.0;
    }

    // Late in stream: consolidate more aggressively (fewer bins preferred).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

