    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(6);

    // Penalize dead space that is too small to be useful later (below min item size ~10),
    // scaled by how far along the stream we are (late dead space is costlier).
