            let ratio = fresh_f / (next_item_size.max(1) as f64);
            if ratio >= 1.0 && ratio < 2.0 {
                score -= 15.0;
            } else if fresh_f < 8.0 {
                score += 15.0;
            }
            if fresh_res == next_item_size {
                score -= 27.0 * (1.0 - progress);
            }
            let fmult = fresh_res / next_item_size;
            let frem = fresh_res % next_item_size;
            if fmult >= 2 && frem <= 2 {
                score -= (fmult.min(5) as f64) * 5.5;
            }
            // Awkward fractional multiples seed fragmentation.
            let frac = ratio - ratio.floor();
            if ratio >= 1.0 && frac > 0.05 && frac < 0.4 {
                score += 11.0 * (0.5 + progress);
            }
        }
        // Never open a fresh bin when the item nearly fills an existing bin exactly.
        if fitting_bins_count >= 1 && bin_capacity - item_size <= 2 {
            score += 50.0;
        }
        // Late-stream fresh bins must be nearly self-closing.
        if progress > 0.7 && fresh_f > 0.0 && fresh_f < next_item_size.max(1) as f64 {
            score += 31.0 * progress;
        }
        if progress > 0.75 && fresh_f >= 12.0 {
            score += 19.0 * (progress - 0.75) * 4.0;
        }
        if progress > 0.8 && open_bins_count > 6 && fresh_f > 4.0 {
            score += 21.0 * progress;
        }
        // NEW: fresh-bin residual must be reusable by the item-size distribution;
        // residuals larger than half capacity but not multiples of next item
        // tend to strand dead space.
        if next_item_size > 0 && fresh_f > capacity_f * 0.5 && fresh_res % next_item_size > 4 {
            score += 12.5 * (0.5 + progress);
        }
        // NEW: opening a fresh bin is worse when many bins are open and the
        // mean residual is still large (existing bins can absorb more).
        if open_bins_count > 3 && mean_residual > fresh_f * 1.4 {
            score += 17.0;
        }
    }

    // Waste-proportional penalty scaled by progress.
    if post_f > 0.0 {
        score += (post_f / capacity_f) * (1.0 + progress) * (1.0 + 0.55 * progress);
    }
    // Tightness term.
    score += (post_f / capacity_f) * (1.0 + progress);

    // Prefer consolidating into fewer open bins.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.6;
    }

    // Nearly-dead bins are cheap to use up.
    if (bin_residual as f64) < mean_residual * 0.3 && bin_residual < bin_capacity {
        score -= 19.0;
    }

    // Half-capacity dead zones seed fragmentation.
    let half = capacity_f * 0.5;
    if post_f > half - 6.0 && post_f < half + 6.0 {
        score += 10.5 * (1.0 - progress);
    }
    if post_f > half && post_f < half + 12.0 {
        score += 6.5 * progress;
    }
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.2 * (0.4 + progress);
    }
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.42 * progress;
    }

    // Quarter/three-quarter awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // NEW: mid-range residual band (15..35) is the most common fragmentation
    // source; penalize slightly more when the next item cannot pair with it.
    if post_f > 15.0 && post_f < 35.0 && next_item_size > 0 {
        let pairable = post_residual >= next_item_size
            || (next_item_size as i64 - post_residual as i64).abs() <= 3;
        if !pairable {
            score += (post_f - 15.0) * 0.30 * (0.5 + progress);
        }
    }

    // Late-stream zero-tolerance.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that belong to "usable" classes.
    // Class by integer division: residuals divisible into common item sizes (10..100) are reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class bonus: post_residual that is a multiple of small denominators
    // (10, 20, 25, 50) tends to be re-fillable by typical items.
    let harmonic_bonus = if post_residual > 0 {
        if post_residual % 10 == 0 { 12.0 }
        else if post_residual % 25 == 0 { 8.0 }
        else if post_residual % 5 == 0 { 4.0 }
        else { 0.0 }
    } else { 0.0 };
    score -= harmonic_bonus;

    // Penalize tiny dead space (1..=5): wasted, unusable slivers
    if post_residual >= 1 && post_residual <= 5 {
        score += 25.0;
    }

    // Penalize residuals that no item (>=1, but realistically >= 10) can use
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Next-item lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 400.0;
        } else {
            score -= 60.0 * (1.0 - gap / cap);
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to how much it overshoots
        score += 10.0 * ((next_item_size - post_residual) as f64 / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default score so that
    // it is only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.05 * (open_bins_count as f64);
        // Late in the stream, slightly discourage opening bins that end mostly empty
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer fuller bins generally: penalize bins whose residual is large relative to mean
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev.max(0.0) - 0.1 * (-dev).max(0.0);

    // Coupling: if post_residual forms a harmonic class matching next item's class, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual % next_item_size.max(1) == 0 {
            score -= 30.0;
        }
    }

    score
}

