        }
        if gap <= 2.0 {
            score -= 13.0;
        }
        let rel = gap / (next_item_size as f64).max(1.0);
        score += rel * 27.0 * (0.6 + 0.4 * progress);
        if gap <= 12.0 && progress < 0.6 {
            score -= 7.5 * (1.0 - progress);
        }
        if gap > post_f * 0.6 {
            score += gap * 0.35 * progress;
        }
        // Trap penalty — residual too small for any plausible future item late.
        if post_f > 0.0 && post_f < 4.0 && progress > 0.5 {
            score += (4.0 - post_f) * 2.2 * progress;
        }
    }

    // Above-average residual left behind is good.
    score -= (post_f - mean_residual) * 0.58;

    // Exact closure reward.
    if post_residual == 0 {
        score -= 950.0;
    } else if bin_residual == item_size && bin_residual < bin_capacity {
        score -= 35.0 + 25.0 * progress;
    }

    // Last-chance bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 118.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 52.0;
        score -= 30.0 * (1.0 - progress);
        let fresh_res = bin_capacity - item_size;
        let fresh_f = fresh_res as f64;
        if next_item_size > 0 && fresh_res >= next_item_size && fresh_res - next_item_size <= 8 {
            score -= 39.0;
        }
        if next_item_size > 0 && (next_item_size as i32 - fresh_res as i32).abs() < 6 {
            score += 15.0 * (1.0 - progress);
        }
        if item_size >= 60 && fresh_res <= 10 {
            score -= 42.0;
        }
        if item_size == bin_capacity {
            score -= 950.0;
        }
        if fitting_bins_count >= 1 && post_residual > 35 {
            score -= 33.0;
        }
        if open_bins_count > 2 && item_size as f64 > capacity_f * 0.8 {
            score += 27.0;
        }
        if fresh_f > 0.0 {
            score += (fresh_f / capacity_f) * 15.0 * progress;
        }
        if fresh_f > 18.0 && fresh_f < capacity_f * 0.45 {
            score += 9.5 * (1.0 - progress);
        }
        // Refuse a fresh bin when an existing bin yields a tight fit.
        if fitting_bins_count >= 1 {
            if post_residual as f64 <= 5.0 {
                score += 78.0;
            } else if post_f > capacity_f * 0.5 {
                score -= 31.0;
            } else if post_f <= capacity_f * 0.25 {
                score += 23.0 * (0.4 + 0.6 * progress);
            }
        }
        if progress < 0.2 && item_size as f64 > capacity_f * 0.65 {
            score -= 21.0;
        }
        // Fresh-bin residual quality — reusable residuals are cheap to open.
        if next_item_size > 0 {
            let ratio = fresh_f / (next_item_size.max(1) as f64);
            if ratio >= 1.0 && ratio < 2.0 {
                score -= 15.0;
            } else if fresh_f < 8.0 {
                score += 15.0;
            }
            if fresh_res == next_item_size {
                score -= 27.0 * (1.0 - progress);
            }
            let fmult = fresh_res / next_item_size;
            let frem = fresh_res % next_item_size;
            if fmult >= 2 && frem <= 2 {
                score -= (fmult.min(5) as f64) * 5.5;
            }
            // Awkward fractional multiples seed fragmentation.
            let frac = ratio - ratio.floor();
            if ratio >= 1.0 && frac > 0.05 && frac < 0.4 {
                score += 11.0 * (0.5 + progress);
            }
            // Fresh residual that is an awkward leftover is dead space from birth.
            if fresh_f < next_item_size as f64 && fresh_f > 0.0 && progress > 0.35 {
                score += (next_item_size as f64 - fresh_f) * 0.55 * progress;
            }
            // Fresh residual divisibility by next item promises a chain.
            if fresh_res % next_item_size == 0 && fresh_res > 0 {
                score -= 12.0 * (0.5 + progress);
            }
        }
        // Never open a fresh bin when the item nearly fills an existing bin exactly.
        if fitting_bins_count >= 1 && bin_capacity - item_size <= 2 {
            score += 50.0;
        }
        // Late-stream fresh bins must be nearly self-closing.
        if progress > 0.7 && fresh_f > 0.0 && fresh_f < next_item_size.max(1) as f64 {
            score += 31.0 * progress;
        }
        if progress > 0.75 && fresh_f >= 12.0 {
            score += 19.0 * (progress - 0.75) * 4.0;
        }
        if progress > 0.8 && open_bins_count > 6 && fresh_f > 4.0 {
            score += 21.0 * progress;
        }
        // Opening a fresh bin is more acceptable when many bins are open and
        // the best existing post-residual is large (consolidation pressure).
        if fitting_bins_count >= 1 && open_bins_count > 5 && post_f > capacity_f * 0.35 {
            score -= 14.0 * ((open_bins_count as f64 - 5.0).min(6.0) / 6.0);
        }
        // COMBINED: fresh residual close to the mean residual is likely reusable.
        if fresh_f > 0.0 && (fresh_f - mean_residual).abs() < 4.0 {
            score -= 8.0 * (0.5 + progress);
        }
    }

    // Waste-proportional penalty scaled by progress.
    if post_f > 0.0 {
        score += (post_f / capacity_f) * (1.0 + progress) * (1.0 + 0.55 * progress);
    }
    // Tightness term.
    score += (post_f / capacity_f) * (1.0 + progress);

    // Prefer consolidating into fewer open bins.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.6;
    }

    // Nearly-dead bins are cheap to use up.
    if (bin_residual as f64) < mean_residual * 0.3 && bin_residual < bin_capacity {
        score -= 19.0;
    }

    // Half-capacity dead zones seed fragmentation.
    let half = capacity_f * 0.5;
    if post_f > half - 6.0 && post_f < half + 6.0 {
        score += 10.5 * (1.0 - progress);
    }
    if post_f > half && post_f < half + 12.0 {
        score += 6.5 * progress;
    }
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.2 * (0.4 + progress);
    }
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.42 * progress;
    }

    // Quarter/three-quarter awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // Late-stream zero-tolerance.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.48 * (progress - 0.72) * 4.0;
    }

    // Dead-space ratio term — penalize candidates whose post-residual cannot
    // pair with the next item even at half its size (true dead space).
    if next_item_size > 0 && post_f > 0.0 && post_f < (next_item_size as f64) * 0.5 {
        score += ((next_item_size as f64) * 0.5 - post_f) * 0.35 * (0.5 + progress);
    }

    // Lookahead-aware dead-space — small residual below next item may still be
    // usable early in the stream; soften the trap penalty accordingly.
    if next_item_size > 0 && post_f > 0.0 && post_f < next_item_size as f64 && post_f <= 10.0 && progress < 0.45 {
        score -= 6.0 * (1.0 - progress);
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let capacity_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect 2-step lookahead match: bin exactly absorbs item + next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 330.0;
    }
    // Near-perfect chain: post residual is an exact multiple of next item.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 3.0 {
            score -= 195.0;
        } else if slack <= 14.0 {
            score -= (58.0 - slack * 0.7).max(-18.0);
        } else {
            score -= (40.0 - slack * 0.35).max(-22.0);
        }
        // Chain compaction: slack itself nearly closes bin after next item.
        if slack < 22.0 {
            score -= (22.0 - slack) * 2.0;
        }
        // Divisibility: residual divisible by next item keeps the chain tight.
        let rem = post_residual % next_item_size;
        if rem <= 3 {
            score -= 16.0 * (1.0 - progress);
        }
        let k = post_residual / next_item_size;
        if k >= 2 && post_residual - k * next_item_size <= 2 {
            score -= 23.0;
        }
        // Multi-step chain depth — deeper chains mean tighter packing.
        let depth = post_residual / next_item_size.max(1);
        if depth >= 3 {
            score -= (depth.min(6) as f64) * 6.0 * (0.5 + progress);
        }
        // Dead-space ratio refinement — stronger penalty for large dead fraction.
        let next_waste = capacity_f - (next_item_size as f64);
        if slack > next_waste * 0.55 {
            score += (slack - next_waste * 0.55) * 1.1 * (0.5 + progress);
        }
        // 3-step lookahead: extendable chain reward.
        if slack >= (next_item_size as f64) {
            score -= 12.0 + 10.0 * progress;
        }
        // Near-multiple slack promises a longer self-sustaining chain.
        let mult = slack as u32 / next_item_size;
        let mrem = slack as u32 % next_item_size;
        if mult >= 1 && mrem <= 1 {
            score -= (mult.min(4) as f64) * 9.0 * (0.6 + progress);
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 29.0 * (0.5 + progress);
        }
        if slack as u32 >= 2 * next_item_size && slack as u32 % (2 * next_item_size) == 0 {
            score -= 16.0 * progress;
        }
        // Two-step tileability — slack that exactly absorbs two more next-size items.
        if next_item_size > 0 && slack as u32 >= 2 * next_item_size && (slack as u32 - 2 * next_item_size) <= 4 {
            score -= 19.0 * (0.5 + progress);
        }
        // Slack tileable by the item size just placed — stream rhythm repeats.
        if item_size > 0 && slack as u32 % item_size <= 1 && slack > 4.0 {
            score -= 10.0 * (0.5 + progress);
        }
        // Tiny tail is near-perfect.
        if slack <= 2 {
            score -= 24.0 * (0.6 + progress);
        }
    }
    // Post-residual too small for the next item: dead space for lookahead.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * (0.5 + 0.24 * gap / capacity_f);
        if gap <= 4.0 && post_f > 0.0 {
            score -= 18.0 * (1.0 - progress);
        }
        if gap <= 2.0 {
            score -= 14.0;
        }
        let rel = gap / (next_item_size as f64).max(1.0);
        score += rel * 27.0 * (0.6 + 0.4 * progress);
        if gap <= 12.0 && progress < 0.6 {
            score -= 7.5 * (1.0 - progress);
        }
        if gap > post_f * 0.6 {
            score += gap * 0.35 * progress;
        }
        // Small gap with a "friendly" post residual (multiple of 5) is recoverable.
        if gap >= 1.0 && gap <= 6.0 && post_residual % 5 <= 2 {
            score -= 5.0 * (1.0 - progress);
        }
        // Large relative gap mid-stream is a fragmentation seed.
        let gap_ratio = gap / (next_item_size as f64).max(1.0);
        if gap_ratio > 0.6 && gap > 14.0 {
            score += gap * 0.24 * (0.5 + progress);
        } else if gap_ratio <= 0.15 && post_f >= 3.0 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Compare post_residual against mean residual: leaving above-average space is good.
    score -= (post_f - mean_residual) * 0.6;

    // Exact closure reward scaled by progress.
    if post_residual == 0 {
        score -= 980.0;
    } else if bin_residual == item_size && bin_residual < bin_capacity {
        score -= 35.0 + 25.0 * progress;
    }

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 125.0;
    }

    // Combined fine-grained fitting + lookahead: bin closes exactly with
    // item + next item — the tightest two-step compaction possible.
    if next_item_size > 0 && bin_residual == item_size + next_item_size {
        score -= 44.0 * (0.6 + progress);
    }
    // Near-closure by item + next item (within 2) is almost as good.
    if next_item_size > 0
        && bin_residual > item_size + next_item_size
        && bin_residual - (item_size + next_item_size) <= 2
    {
        score -= 19.0 * (0.5 + progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 55.0;
        score -= 30.0 * (1.0 - progress);
        let fresh_res = bin_capacity - item_size;
        let fresh_f = fresh_res as f64;
        if next_item_size > 0 && fresh_res >= next_item_size && fresh_res - next_item_size <= 8 {
            score -= 40.0;
        }
        if next_item_size > 0 && (next_item_size as i32 - fresh_res as i32).abs() < 6 {
            score += 16.0 * (1.0 - progress);
        }
        if item_size >= 60 && fresh_res <= 10 {
            score -= 45.0;
        }
        if item_size == bin_capacity {
            score -= 980.0;
        }
        if fitting_bins_count >= 1 && post_residual > 35 {
            score -= 35.0;
        }
        if open_bins_count > 2 && item_size as f64 > capacity_f * 0.8 {
            score += 28.0;
        }
        if fresh_f > 0.0 {
            score += (fresh_f / capacity_f) * 15.0 * progress;
        }
        if fresh_f > 18.0 && fresh_f < capacity_f * 0.45 {
            score += 9.5 * (1.0 - progress);
        }
        // Refuse a fresh bin when some existing bin already yields a tight fit.
        if fitting_bins_count >= 1 {
            if post_residual as f64 <= 5.0 {
                score += 85.0;
            } else if post_f > capacity_f * 0.5 {
                score -= 33.0;
            } else if post_f <= capacity_f * 0.25 {
                score += 24.0 * (0.4 + 0.6 * progress);
            }
        }
        if progress < 0.2 && item_size as f64 > capacity_f * 0.65 {
            score -= 21.0;
        }
        // Fresh-bin residual quality — reusable residuals are cheap to open.
        if next_item_size > 0 {
            let ratio = fresh_f / (next_item_size.max(1) as f64);
            if ratio >= 1.0 && ratio < 2.0 {
                score -= 16.0;
            } else if fresh_f < 8.0 {
                score += 16.0;
            }
            if fresh_res == next_item_size {
                score -= 29.0 * (1.0 - progress);
            }
            let fmult = fresh_res / next_item_size;
            let frem = fresh_res % next_item_size;
            if fmult >= 2 && frem <= 2 {
                score -= (fmult.min(5) as f64) * 6.0;
            }
            // Awkward fractional multiples seed fragmentation.
            let frac = ratio - ratio.floor();
            if ratio >= 1.0 && frac > 0.05 && frac < 0.4 {
                score += 12.0 * (0.5 + progress);
            }
            // Fresh residual tileable by next item with tiny remainder.
            if fresh_res > next_item_size && fresh_res % next_item_size <= 1 {
                score -= 13.0 * (1.0 - progress);
            }
            // Large fresh residual that cannot fit next item late-stream is dead space.
            if fresh_f > capacity_f * 0.5 && fresh_f < next_item_size as f64 && progress > 0.3 {
                score += 26.0 * progress;
            }
        }
        // Never open a fresh bin when the item nearly fills an existing bin exactly.
        if fitting_bins_count >= 1 && bin_capacity - item_size <= 2 {
            score += 55.0;
        }
        // Late-stream fresh bins must be nearly self-closing.
        if progress > 0.7 && fresh_f > 0.0 && fresh_f < next_item_size.max(1) as f64 {
            score += 33.0 * progress;
        }
        if progress > 0.75 && fresh_f >= 12.0 {
            score += 20.0 * (progress - 0.75) * 4.0;
        }
        if progress > 0.8 && open_bins_count > 6 && fresh_f > 4.0 {
            score += 22.0 * progress;
        }
        // Fresh residual tileable by small common sizes is a recoverable seed.
        if fresh_res > 0 && fresh_res <= 48 && progress < 0.55
            && (fresh_res % 4 == 0 || fresh_res % 6 == 0 || fresh_res % 8 == 0 || fresh_res % 12 == 0) {
            score -= 7.0 * (1.0 - progress);
        }
        // Refuse a fresh bin when an existing bin gives a perfect or near-perfect
        // two-step chain (dead-space guard).
        if next_item_size > 0 && fitting_bins_count >= 1
            && (post_residual == next_item_size
                || (post_residual > next_item_size && post_residual - next_item_size <= 3)) {
            score += 65.0;
        }
        // Refuse a fresh bin when an existing bin closes exactly with item + next item.
        if next_item_size > 0 && fitting_bins_count >= 1
            && bin_capacity == item_size + next_item_size {
            score += 58.0;
        }
        // New guard: refuse fresh bin when any open bin can absorb item + next item
        // with tiny leftover — the strongest anti-fragmentation lookahead.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let two = item_size + next_item_size;
            if bin_residual >= two && bin_residual - two <= 4 {
                score += 48.0;
            }
        }
    }

    // Waste-proportional penalty scaled by stream progress.
    if post_f > 0.0 {
        score += (post_f / capacity_f) * (1.0 + progress) * (1.0 + 0.55 * progress);
    }
    // Prefer filling bins tightly as the stream progresses.
    score += (post_f / capacity_f) * (1.0 + progress);

    // Slight penalty for spreading across many open bins.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.6;
    }

    // Fragmentation guard: nearly-dead bins are cheap to use up.
    if (bin_residual as f64) < mean_residual * 0.3 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Dead-space entropy guard: residuals near half capacity seed fragmentation.
    let half = capacity_f * 0.5;
    if post_f > half - 6.0 && post_f < half + 6.0 {
        score += 11.0 * (1.0 - progress);
    }
    if post_f > half && post_f < half + 12.0 {
        score += 6.5 * progress;
    }
    if post_f > half - 12.0 && post_f <= half - 6.0 && open_bins_count > 4 {
        score += 4.0 * (1.0 - progress);
    }

    // Tiny residuals are premium targets — squeeze them hard mid-stream.
    if post_f > 0.0 && post_f <= 6.0 {
        score -= (7.0 - post_f) * 3.4 * (0.4 + progress);
    }
    if post_f > 6.0 && post_f <= 15.0 && progress > 0.4 {
        score += (post_f - 6.0) * 0.42 * progress;
    }

    // Quarter/three-quarter dead zones are awkward anchors.
    let quarter = capacity_f * 0.25;
    let three_quarter = capacity_f * 0.75;
    if post_f > quarter && post_f < quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }
    if post_f > three_quarter && post_f < three_quarter + 5.0 {
        score += 5.5 * (1.0 - progress);
    }

    // Tiny tail after next item is near-perfect.
    if next_item_size > 0 && post_residual > next_item_size {
        let tail = post_residual - next_item_size;
        if tail > 0 && tail <= 2 {
            score -= 23.0 * (0.6 + progress);
        }
    }

    // Dead-space ratio term.
    if next_item_size > 0 && post_f > 0.0 {
        let dsr = post_f / (next_item_size as f64).max(1.0);
        if dsr < 0.25 && post_residual < next_item_size {
            score += 8.0 * (0.5 + progress);
        } else if dsr >= 2.0 && dsr <= 4.0 {
            score -= 6.5 * (1.0 - progress);
        }
    }

    // Late-stream zero-tolerance — tighten harder near the end.
    if progress > 0.72 && post_f > 0.0 {
        score += post_f * 0.5 * (progress - 0.72) * 4.0;
    }

    // Late-stream tightening.
    score *= 1.0 + 0.29 * progress;

    // Deterministic tie-breaker.
    score += (post_residual % 10) as f64 * 0.05;

    score
}
